INSERT INTO cantrip_editorial_plan VALUES ($cantrip_plan${"application_id":"cantrip-editorial-20261014","concept":{"concept_id":"spellcasting_modifier","name":"МЗ","name_en":"Spellcasting Ability Modifier","sort_order":90,"description":"МЗ — модификатор заклинательной характеристики, указанной классом или источником заклинания. Это модификатор Интеллекта, Мудрости или Харизмы, используемый для данного заклинания.\n\nБонус атаки заклинанием = БМ + МЗ. СЛ спасброска заклинания = 8 + БМ + МЗ. БМ — бонус мастерства. Если описание добавляет МЗ к урону или лечению, добавляется только [[модификатор характеристики|concept:ability_score_and_modifier]], без БМ.\n\nВ листе персонажа формула использует характеристику конкретного источника заклинания; при нескольких источниках она может различаться."},"entries":[{"id":"3b0ac4ac-73bb-4525-83fa-9f4a9a14c430","card_number":"SPELL-0166","name":"Брызги кислоты","before":{"description":"Вы создаёте кислотный пузырь, который взрывается Сферой радиусом 5 футов, с центром в точке в пределах дистанции. Каждое существо в этой Сфере должно преуспеть в спасброске Ловкости, иначе получит [acid]1к6:acid:кислотой[/acid].","detailed_description":null,"upcast_description":"Урон увеличивается на 1к6, когда вы достигаете 5‑го уровня (2к6), 11‑го уровня (3к6) и 17‑го уровня (4к6)."},"after":{"description":"Вы создаёте кислотный пузырь, который взрывается [[Сферой|concept:sphere]] радиусом 5 футов, с центром в точке в пределах дистанции. Каждое существо в этой Сфере должно преуспеть в [[спасброске|concept:saving_throw_]] Ловкости, иначе получит [acid]1к6:acid:кислотой[/acid].","detailed_description":"Вы создаёте кислотный пузырь, который взрывается [[Сферой|concept:sphere]] радиусом 5 футов, с центром в точке в пределах дистанции. Каждое существо в этой Сфере должно преуспеть в [[спасброске|concept:saving_throw_]] Ловкости, иначе получит [acid]1к6:acid:кислотой[/acid].","upcast_description":"Урон увеличивается на 1к6, когда вы достигаете 5‑го уровня (2к6), 11‑го уровня (3к6) и 17‑го уровня (4к6)."},"expected_mechanics":{"activation":{"cost":[{"resource":"action"}],"mode":"active"},"effects":[{"ability":"dex","dc":"8 + prof + spellcasting","on_fail":[{"dice":"1d6","kind":"damage","scaling":{"dice":"1d6","per":"character_level"},"type":"acid"}],"on_success":[],"resolution":"save","who":"target"}],"spell_class_list_ids":["CLASS-sorcerer","CLASS-wizard"],"targeting":{"actor_targets":true,"allowed_relations":["self","ally","enemy","neutral"],"area":{"kind":"sphere","radius_ft":5},"domain":"actor","max_targets":8,"min_targets":1,"range_ft":60,"requires_line_of_sight":true,"shape":"area"}}},{"id":"70e35366-5446-49ff-b0b9-759dbbff347e","card_number":"SPELL-0173","name":"Волшебная рука","before":{"description":"В точке, выбранной вами в пределах дистанции, появляется призрачная парящая рука. Рука существует, пока заклинание активно. Рука исчезает, если окажется более чем в 30 футах от вас, или если вы повторно сотворите это заклинание.","detailed_description":"В точке, выбранной вами в пределах дистанции, появляется призрачная парящая рука. Рука существует, пока заклинание активно. Рука исчезает, если окажется более чем в 30 футах от вас, или если вы повторно сотворите это заклинание.\n\nВы можете использовать эту руку для манипулирования объектами, открывать незапертые двери и контейнеры, убрать предметы в открытые контейнеры или доставать их оттуда, или выливать содержимое флаконов.\n\n:action:Действием Магия в течение следующих ходов вы можете контролировать руку таким же образом. Частью этого действия вы можете перемещать руку на расстояние не более 30 футов. Рука не может атаковать, активировать магические предметы и переносить более 10 фунтов.","upcast_description":null},"after":{"description":"Создайте призрачную руку в пределах 30 футов на 1 минуту. При сотворении и затем [[действием|concept:action]] [[Магия|concept:magic]] она может перемещать предметы, открывать незапертые двери и контейнеры или выливать содержимое флакона. При управлении рука перемещается до 30 футов; переносит до 10 фунтов, не атакует и не активирует магические предметы. Исчезает дальше 30 футов от вас или при повторном сотворении.","detailed_description":"В выбранной вами точке в пределах дистанции появляется призрачная парящая рука. Она существует 1 минуту, но исчезает, если окажется дальше 30 футов от вас или если вы снова сотворите это заклинание.\n\nУже при сотворении вы можете использовать руку, чтобы манипулировать объектом, открыть незапертую дверь или контейнер, убрать предмет в открытый контейнер или достать его оттуда либо вылить содержимое флакона.\n\nВ следующие ходы вы можете вновь управлять рукой [[действием|concept:action]] [[Магия|concept:magic]]. Частью этого действия можно переместить её до 30 футов.\n\nРука не может атаковать, активировать магические предметы или переносить более 10 фунтов.","upcast_description":null},"expected_mechanics":{"activation":{"cost":[{"resource":"action"}],"mode":"active"},"effects":[{"resolution":"auto","result":[{"allowed_operations":["move_object","open_unlocked_door","open_unlocked_container","stow_item","retrieve_item","pour_vial"],"duration":{"amount":10,"type":"rounds"},"forbidden_operations":["attack","activate_magic_item","carry_over_limit"],"kind":"remote_manipulator","max_distance_ft":30,"max_load_lb":10,"move_per_action_ft":30,"stack_id":"spell:mage-hand","stack_type":"overwrite"},{"description":"Рука готова к управлению. В активном эффекте «Волшебная рука» выберите «Управлять рукой», укажите объект, операцию, расстояние и вес. Каждая команда руке расходует основное действие и сохраняется в журнале.","kind":"narrative"}]}],"spell_class_list_ids":["CLASS-bard","CLASS-sorcerer","CLASS-warlock","CLASS-wizard"],"targeting":{"actor_targets":false,"allowed_relations":["self"],"domain":"actor","max_targets":1,"min_targets":0,"range_ft":0,"requires_line_of_sight":false,"shape":"self"}}},{"id":"5da8fe39-f54d-4ffb-a958-4ed6d9cafaa2","card_number":"SPELL-0192","name":"Дружба","before":{"description":"Вы волшебным образом излучаете чувство дружбы по отношению к одному существу, которое вы можете видеть в пределах дистанции. Цель должна преуспеть в спасброске Мудрости, иначе станет [[Очарованной|effect:ed7cc8d3-1af0-4af7-af13-046341f21491]] на время длительности.","detailed_description":"Вы волшебным образом излучаете чувство дружбы по отношению к одному существу, которое вы можете видеть в пределах дистанции.\n\nЦель должна преуспеть в спасброске Мудрости, иначе станет [[Очарованной|effect:ed7cc8d3-1af0-4af7-af13-046341f21491]] на время длительности. Цель автоматически преуспевает, если не является Гуманоидом, если вы сражаетесь с ней, или если вы сотворяли это заклинание на неё за последние 24 часа.\n\nЗаклинание заканчивается досрочно, если цель получает урон, или если вы совершаете [[бросок атаки|concept:attack_roll]], наносите урон или вынуждаете кого‑либо совершить [[спасбросок|concept:saving_throw_]]. Когда заклинание заканчивается, цель знает, что была [[Очарованной|effect:ed7cc8d3-1af0-4af7-af13-046341f21491]] вами.","upcast_description":null},"after":{"description":"Видимое существо в пределах 10 футов совершает [[спасбросок|concept:saving_throw_]] Мудрости: при провале оно [[Очаровано|effect:ed7cc8d3-1af0-4af7-af13-046341f21491]] вами до 1 минуты [[концентрации|concept:concentration]]. Не-гуманоид, противник в текущем бою или цель этого заклинания за последние 24 часа автоматически преуспевает. Получение целью урона либо ваша атака, нанесение урона или принуждение к спасброску прекращают заклинание. После окончания цель знает об очаровании.","detailed_description":"Вы волшебным образом излучаете чувство дружбы по отношению к одному существу, которое вы можете видеть в пределах дистанции.\n\nЦель должна преуспеть в [[спасброске|concept:saving_throw_]] Мудрости, иначе станет [[Очарованной|effect:ed7cc8d3-1af0-4af7-af13-046341f21491]] на время длительности. Цель автоматически преуспевает, если не является Гуманоидом, если вы сражаетесь с ней, или если вы сотворяли это заклинание на неё за последние 24 часа.\n\nЗаклинание заканчивается досрочно, если цель получает урон, или если вы совершаете [[бросок атаки|concept:attack_roll]], наносите урон или вынуждаете кого‑либо совершить спасбросок. Когда заклинание заканчивается, цель знает, что была Очарованной вами.","upcast_description":null},"expected_mechanics":{"activation":{"cost":[{"resource":"action"}],"mode":"active"},"effects":[{"ability":"wis","automatic_success":{"if_target_creature_type_not":"humanoid","if_target_relation":"enemy"},"dc":"8 + prof + spellcasting","on_fail":[{"duration":{"amount":10,"concentration":true,"type":"rounds"},"kind":"condition","op":"apply","value":"charmed"}],"on_success":[],"resolution":"save","who":"target"}],"spell_class_list_ids":["CLASS-bard","CLASS-sorcerer","CLASS-warlock","CLASS-wizard"],"targeting":{"filter":"any","range":"10 футов","shape":"single"}}},{"id":"d3a05e09-7f80-44ea-be21-dfdd3408d528","card_number":"SPELL-0194","name":"Дубинка","before":{"description":"Дубинка или Боевой посох, который вы держите, наполняется силой природы. Пока заклинание активно, вы можете использовать свою заклинательную характеристику вместо Силы для бросков атаки и урона рукопашных атак этим оружием, а кость урона этого оружия заменяется на к8.","detailed_description":"Дубинка или Боевой посох, который вы держите, наполняется силой природы. Пока заклинание активно, вы можете использовать свою заклинательную характеристику вместо Силы для бросков атаки и урона рукопашных атак этим оружием, а кость урона этого оружия заменяется на к8.\n\nЕсли эта атака наносит урон, то это может быть урон [force]:force:Чистой силой[/force] или обычный тип урона от этого оружия (по вашему выбору). Заклинание заканчивается, если вы сотворите его снова или выпустите это оружие из рук.","upcast_description":"Кость урона меняется, когда вы достигаете 5‑го уровня (к10), 11‑го уровня (к12) и 17‑го уровня (2к6)."},"after":{"description":"Дубинка или Боевой посох, который вы держите, наполняется силой природы. Пока заклинание активно, вы можете использовать свою [[заклинательную характеристику|concept:ability_score_and_modifier]] вместо Силы для [[бросков атаки|concept:attack_roll]] и урона рукопашных атак этим оружием, а кость урона этого оружия заменяется на к8.\n\nЕсли эта атака наносит урон, то это может быть урон [force]:force:Чистой силой[/force] или обычный тип урона от этого оружия (по вашему выбору). Заклинание заканчивается, если вы сотворите его снова или выпустите это оружие из рук.","detailed_description":"Дубинка или Боевой посох, который вы держите, наполняется силой природы. Пока заклинание активно, вы можете использовать свою [[заклинательную характеристику|concept:ability_score_and_modifier]] вместо Силы для [[бросков атаки|concept:attack_roll]] и урона рукопашных атак этим оружием, а кость урона этого оружия заменяется на к8.\n\nЕсли эта атака наносит урон, то это может быть урон [force]:force:Чистой силой[/force] или обычный тип урона от этого оружия (по вашему выбору). Заклинание заканчивается, если вы сотворите его снова или выпустите это оружие из рук.","upcast_description":"Кость урона меняется, когда вы достигаете 5‑го уровня (к10), 11‑го уровня (к12) и 17‑го уровня (2к6)."},"expected_mechanics":{"activation":{"cost":[{"resource":"bonus_action"}],"mode":"active"},"effects":[{"context":"in_play","count":1,"id":"shillelagh_weapon","kind":"choice","options":{"filter":["club","quarterstaff"],"source":"equipped_weapon"},"prompt":"Выберите удерживаемую дубинку или боевой посох"},{"context":"in_play","count":1,"id":"shillelagh_damage_type","kind":"choice","options":{"items":[{"grants":[{"description":"Сохраняется обычный тип урона оружия.","kind":"narrative"}],"id":"weapon","name":"Обычный тип оружия"},{"grants":[{"description":"Основной урон оружия становится уроном силовым полем.","kind":"narrative"}],"id":"force","name":"Силовое поле"}],"source":"explicit"},"prompt":"Выберите тип урона"},{"resolution":"auto","result":[{"damage_scaling":[{"dice":"1d8","min_level":1},{"dice":"1d10","min_level":5},{"dice":"1d12","min_level":11},{"dice":"2d6","min_level":17}],"damage_type_choice_id":"shillelagh_damage_type","duration":{"amount":10,"type":"rounds"},"eligible_weapon_types":["club","quarterstaff"],"kind":"weapon_enchantment","stack_id":"spell:shillelagh","stack_type":"overwrite","weapon_choice_id":"shillelagh_weapon"},{"description":"Эффект применяется только пока выбранная карта остаётся в руке; физическое отпускание оружия вне листа требует события адаптера экипировки.","kind":"narrative"}]}],"spell_class_list_ids":["CLASS-druid"],"targeting":{"actor_targets":false,"allowed_relations":["self"],"domain":"actor","max_targets":1,"min_targets":0,"range_ft":0,"requires_line_of_sight":false,"shape":"self"}}},{"id":"73d4195c-5da4-444d-a0c1-19572df641b2","card_number":"SPELL-0202","name":"Защита от оружия","before":{"description":"Когда существо совершает [[бросок атаки|concept:attack_roll]] по вам до окончания действия заклинания, атакующий вычитает 1к4 из броска атаки.","detailed_description":null,"upcast_description":null},"after":{"description":"Когда существо совершает [[бросок атаки|concept:attack_roll]] по вам до окончания действия заклинания, атакующий вычитает 1к4 из броска атаки.","detailed_description":"Когда существо совершает [[бросок атаки|concept:attack_roll]] по вам до окончания действия заклинания, атакующий вычитает 1к4 из броска атаки.","upcast_description":null},"expected_mechanics":{"activation":{"cost":[{"resource":"action"}],"mode":"active"},"effects":[{"resolution":"auto","result":[{"applies_to":{"roll":"attack"},"duration":{"amount":10,"concentration":true,"type":"rounds"},"faces":4,"kind":"modifier","op":"bonus_die","scope":"target","sign":-1,"source":"Защита от оружия"}]}],"spell_class_list_ids":["CLASS-bard","CLASS-sorcerer","CLASS-warlock","CLASS-wizard"],"targeting":{"shape":"self"}}},{"id":"7f7d92ed-0d5c-4567-990b-3395247b9266","card_number":"SPELL-0204","name":"Звёздный светлячок","before":{"description":"Вы запускаете частицу света в одно существо или объект в пределах дистанции. Совершите Дальнобойную [[атаку заклинанием|concept:spell_attack]] по цели. При попадании цель получает [radiant]1к8:radiant:излучением[/radiant], и до конца вашего следующего хода испускает [[Тусклый свет|concept:dim_light]] в пределах 10 футов и не получает преимуществ от состояния [[Невидимый|effect:a33608fe-4378-465d-a81a-85920104ffc4]].","detailed_description":null,"upcast_description":"Урон заклинания увеличивается на 1к8, когда вы достигаете 5‑го уровня (2к8), 11‑го уровня (3к8) и 17‑го уровня (4к8)."},"after":{"description":"Вы запускаете частицу света в одно существо или объект в пределах дистанции. Совершите Дальнобойную [[атаку заклинанием|concept:spell_attack]] по цели. При попадании цель получает [radiant]1к8:radiant:излучением[/radiant], и до конца вашего следующего хода испускает [[Тусклый свет|concept:dim_light]] в пределах 10 футов и не получает преимуществ от состояния [[Невидимый|effect:a33608fe-4378-465d-a81a-85920104ffc4]].","detailed_description":"Вы запускаете частицу света в одно существо или объект в пределах дистанции. Совершите Дальнобойную [[атаку заклинанием|concept:spell_attack]] по цели. При попадании цель получает [radiant]1к8:radiant:излучением[/radiant], и до конца вашего следующего хода испускает [[Тусклый свет|concept:dim_light]] в пределах 10 футов и не получает преимуществ от состояния [[Невидимый|effect:a33608fe-4378-465d-a81a-85920104ffc4]].","upcast_description":"Урон заклинания увеличивается на 1к8, когда вы достигаете 5‑го уровня (2к8), 11‑го уровня (3к8) и 17‑го уровня (4к8)."},"expected_mechanics":{"activation":{"cost":[{"resource":"action"}],"mode":"active"},"effects":[{"ability":"spellcasting","attack_kind":"spell_ranged","on_hit":[{"dice":"1d8","kind":"damage","scaling":{"dice":"1d8","per":"character_level"},"type":"radiant"},{"description":"До конца следующего хода цель излучает тусклый свет и не получает преимуществ от Невидимости.","kind":"narrative"}],"resolution":"attack_roll","vs":"ac"}],"spell_class_list_ids":["CLASS-bard","CLASS-druid"],"targeting":{"filter":"any","range":"60 футов","shape":"single"}}},{"id":"bdeda1c3-6574-4946-8b91-5faf0f76072c","card_number":"SPELL-0205","name":"Злая насмешка","before":{"description":"Вы испускаете на существо, которое вы можете видеть или слышать в пределах дистанции, поток оскорблений вперемешку с тонкой магией. Цель должна преуспеть в спасброске Мудрости, иначе получит [psychic]1к6:psychic:психической энергией[/psychic] и совершит с [[Помехой|concept:disadvantage]] следующий [[бросок атаки|concept:attack_roll]] до конца своего следующего хода.","detailed_description":null,"upcast_description":"Урон увеличивается на 1к6, когда вы достигаете 5‑го уровня (2к6), 11‑го уровня (3к6) и 17‑го уровня (4к6)."},"after":{"description":"Вы испускаете на существо, которое вы можете видеть или слышать в пределах дистанции, поток оскорблений вперемешку с тонкой магией. Цель должна преуспеть в [[спасброске|concept:saving_throw_]] Мудрости, иначе получит [psychic]1к6:psychic:психической энергией[/psychic] и совершит с [[Помехой|concept:disadvantage]] следующий [[бросок атаки|concept:attack_roll]] до конца своего следующего хода.","detailed_description":"Вы испускаете на существо, которое вы можете видеть или слышать в пределах дистанции, поток оскорблений вперемешку с тонкой магией. Цель должна преуспеть в [[спасброске|concept:saving_throw_]] Мудрости, иначе получит [psychic]1к6:psychic:психической энергией[/psychic] и совершит с [[Помехой|concept:disadvantage]] следующий [[бросок атаки|concept:attack_roll]] до конца своего следующего хода.","upcast_description":"Урон увеличивается на 1к6, когда вы достигаете 5‑го уровня (2к6), 11‑го уровня (3к6) и 17‑го уровня (4к6)."},"expected_mechanics":{"activation":{"cost":[{"resource":"action"}],"mode":"active"},"effects":[{"ability":"wis","dc":"8 + prof + spellcasting","on_fail":[{"dice":"1d6","kind":"damage","scaling":{"dice":"1d6","per":"character_level"},"type":"psychic"},{"kind":"grant_effect","value":"EFFECT-runtime-b6cca2b1f49ad5799799"}],"on_success":[],"resolution":"save","who":"target"}],"spell_class_list_ids":["CLASS-bard"],"targeting":{"filter":"enemy","range":"60 футов","shape":"single"}}},{"id":"3c68b9a7-d143-4b39-b06c-3d78e3276117","card_number":"druidcraft","name":"Искусство друидов","before":{"description":"Создайте один небольшой эффект природы: предскажите погоду, ускорьте цветение, вызовите безвредное ощущение или зажгите либо потушите небольшой огонь.","detailed_description":"Пошептавшись с духами природы, вы создаёте один из нижеперечисленных эффектов в пределах дистанции.\n**Датчик погоды.** Вы создаёте Крошечный безвредный ощутимый эффект, предсказывающий погоду в текущем месте в течение следующих 24 часов. Это может быть золотистый шарик, означающий ясную погоду, облачко, означающее дождь, снежинка и так далее.\n\nЭффект длится 1 раунд.\n**Цветение.** Вы мгновенно заставляете цветок распуститься, семечко прорасти или почку раскрыться.\n**Ощутимый эффект**. Вы создаёте мгновенный безвредный ощутимый эффект, такой как падающие листья, спектральные танцующие феи, порыв ветра, звук маленького животного или слабый запах скунса.\n\nЭффект должен помещаться в Куб со стороной 5 футов.\n**Игра с огнём**. Вы зажигаете или тушите свечу, факел или костёр.","upcast_description":null},"after":{"description":"Создайте один небольшой эффект природы: предскажите погоду, ускорьте цветение, вызовите безвредное ощущение или зажгите либо потушите небольшой [fire]:fire:огонь[/fire].","detailed_description":"Вы создаёте один из следующих эффектов природы в пределах дистанции.\n\n**Датчик погоды.** Крошечный безвредный сенсорный эффект предсказывает погоду в вашем текущем месте на следующие 24 часа: например, золотистый шар означает ясную погоду, облачко — дождь, снежинка — снег. Сам эффект длится 1 раунд.\n\n**Цветение.** Вы мгновенно заставляете цветок распуститься, семечко прорасти или почку раскрыться.\n\n**Ощутимый эффект.** Вы создаёте безвредный сенсорный эффект: падающие листья, призрачных танцующих фей, лёгкий ветерок, [thunder]:thunder:звук[/thunder] животного или слабый запах скунса. Эффект помещается в [[Куб|concept:cube]] со стороной 5 футов.\n\n**Игра с огнём.** Вы зажигаете или тушите свечу, факел или костёр.","upcast_description":null},"expected_mechanics":{"activation":{"cast_time":{"amount":1,"unit":"action"},"cost":[{"resource":"action"}],"mode":"active"},"effects":[{"resolution":"auto","result":[]}],"primitive":{"policy":{"sensory_cube_side_ft":5,"weather_duration_rounds":1},"type":"druidcraft_world"},"spell_class_list_ids":["CLASS-druid"],"targeting":{"actor_targets":false,"allowed_relations":[],"domain":"world","filter":"any","max_targets":1,"min_targets":0,"range":"30 футов","range_ft":30,"requires_line_of_sight":false,"shape":"single"}}},{"id":"e300a1f2-91ae-4c82-9904-057f93a013ba","card_number":"chill_touch","name":"Леденящее прикосновение","before":{"description":"Проводя могильный холод через себя, совершите рукопашную [[атаку заклинанием|concept:spell_attack]] по цели в пределах досягаемости. При попадании цель получает [necrotic]1к10:necrotic:некротической энергией[/necrotic] и не может восстанавливать [[Хиты|concept:hit_points]] до конца вашего следующего хода.","detailed_description":null,"upcast_description":"Урон увеличивается на 1к10, когда вы достигаете 5‑го уровня (2к10), 11‑го уровня (3к10) и 17‑го уровня (4к10)."},"after":{"description":"Проводя могильный [cold]:cold:холод[/cold] через себя, совершите рукопашную [[атаку заклинанием|concept:spell_attack]] по цели в пределах досягаемости. При попадании цель получает [necrotic]1к10:necrotic:некротической энергией[/necrotic] и не может восстанавливать [[Хиты|concept:hit_points]] до конца вашего следующего хода.","detailed_description":"Проводя могильный [cold]:cold:холод[/cold] через себя, совершите рукопашную [[атаку заклинанием|concept:spell_attack]] по цели в пределах досягаемости. При попадании цель получает [necrotic]1к10:necrotic:некротической энергией[/necrotic] и не может восстанавливать [[Хиты|concept:hit_points]] до конца вашего следующего хода.","upcast_description":"Урон увеличивается на 1к10, когда вы достигаете 5‑го уровня (2к10), 11‑го уровня (3к10) и 17‑го уровня (4к10)."},"expected_mechanics":{"activation":{"cast_time":{"amount":1,"unit":"action"},"cost":[{"resource":"action"}],"mode":"active"},"effects":[{"ability":"spellcasting","attack_kind":"spell_melee","on_hit":[{"dice":"1d10","kind":"damage","scaling":{"dice":"1d10","per":"character_level"},"type":"necrotic"},{"kind":"grant_effect","value":"EFFECT-runtime-5eb1f3085f46c801502a"}],"resolution":"attack_roll","vs":"ac"}],"interaction":{"intent":"harmful"},"spell_class_list_ids":["CLASS-sorcerer","CLASS-warlock","CLASS-wizard"],"targeting":{"actor_targets":true,"allowed_relations":["self","ally","enemy","neutral"],"domain":"actor","filter":"any","max_targets":1,"min_targets":1,"range":"Касание","range_ft":5,"requires_line_of_sight":false,"requires_touch":true,"shape":"single"}}},{"id":"ebe432dd-c124-4f79-a39b-db14ca2ed741","card_number":"SPELL-0218","name":"Луч холода","before":{"description":"Холодный сине-белый луч устремляется к существу, находящемуся в пределах дистанции. Совершите Дальнобойную [[атаку заклинанием|concept:spell_attack]] по цели. При попадании цель получает [cold]1к8:cold:холодом[/cold], а её Скорость уменьшается на 10 футов до начала вашего следующего хода.","detailed_description":null,"upcast_description":"Урон заклинания увеличивается на 1к8, когда вы достигаете 5‑го уровня (2к8), 11‑го уровня (3к8) и 17‑го уровня (4к8)."},"after":{"description":"Холодный сине-белый луч устремляется к существу, находящемуся в пределах дистанции. Совершите Дальнобойную [[атаку заклинанием|concept:spell_attack]] по цели. При попадании цель получает [cold]1к8:cold:холодом[/cold], а её [[Скорость|concept:speed]] уменьшается на 10 футов до начала вашего следующего хода.","detailed_description":"Холодный сине-белый луч устремляется к существу, находящемуся в пределах дистанции. Совершите Дальнобойную [[атаку заклинанием|concept:spell_attack]] по цели. При попадании цель получает [cold]1к8:cold:холодом[/cold], а её [[Скорость|concept:speed]] уменьшается на 10 футов до начала вашего следующего хода.","upcast_description":"Урон заклинания увеличивается на 1к8, когда вы достигаете 5‑го уровня (2к8), 11‑го уровня (3к8) и 17‑го уровня (4к8)."},"expected_mechanics":{"activation":{"cast_time":{"amount":1,"unit":"action"},"cost":[{"resource":"action"}],"mode":"active"},"effects":[{"ability":"spellcasting","attack_kind":"spell_ranged","on_hit":[{"dice":"1d8","kind":"damage","scaling":{"dice":"1d8","per":"character_level"},"type":"cold"},{"kind":"grant_effect","value":"EFFECT-runtime-faaeb2dc602fce1c3f5a"}],"resolution":"attack_roll","vs":"ac"}],"interaction":{"intent":"harmful"},"spell_class_list_ids":["CLASS-sorcerer","CLASS-wizard"],"targeting":{"actor_targets":true,"allowed_relations":["self","ally","enemy","neutral"],"domain":"actor","filter":"any","max_targets":1,"min_targets":1,"range":"60 футов","range_ft":60,"requires_line_of_sight":true,"shape":"single"}}},{"id":"dc59ce91-4e89-4f1d-89a5-e25650f3a6b7","card_number":"minor_illusion","name":"Малая иллюзия","before":{"description":"Вы создаёте звук или изображение объекта в пределах дистанции на время действия заклинания. Звук может быть любым — от шёпота до крика; изображение — неподвижный объект не больше Куба со стороной 5 футов, без звука, света и запаха.\n\n:action:Действием Изучение (проверка Интеллекта против СЛ ваших заклинаний) существо может распознать иллюзию; сквозь образ всё проходит, что также выдаёт обман.","detailed_description":"Вы создаёте звук или изображение объекта в пределах дистанции, которое сохраняется пока заклинание активно. Ниже описаны эффекты каждого из типов иллюзии. Иллюзия исчезает, если вы снова сотворяете это заклинание. Если существо совершает действие Изучение применительно к звуку или изображению, оно может определить, что это иллюзия, преуспев в проверке Интеллекта (Расследование) против Сл [[спасброска|concept:saving_throw_]] ваших заклинаний.\n\nЕсли существо распознаёт иллюзию, она для него притупляется. Звук. Если вы создаёте звук, его громкость может варьироваться от шёпота до крика. Это может быть ваш голос, чужой голос, рык льва, бой барабанов или любой другой звук по вашему выбору.\n\nЗвук не ослабевает на протяжении всей длительности, и вы можете издавать отдельные звуки в разное время пока заклинание активно. Изображение. Если вы создаёте изображение объекта — например, стула, грязных следов ног или маленького сундука, — оно должно быть не больше Куба со стороной 5 футов.\n\nИзображение не может создавать звук, свет, запах или какой‑либо другой сенсорный эффект. Физическое взаимодействие с образом даёт понять, что это иллюзия, потому что сквозь него всё проходит.","upcast_description":null},"after":{"description":"Создайте [thunder]:thunder:звук[/thunder] или изображение объекта на 1 минуту. [thunder]:thunder:Звук[/thunder] может быть любым, непрерывным или прерывистым; изображение помещается в [[Куб|concept:cube]] со стороной 5 футов и не создаёт других ощущений. [[Действием|concept:action]] [[Изучение|concept:study]] существо может распознать иллюзию проверкой Интеллекта (Расследование) против [[СЛ|concept:difficulty_class]] ваших заклинаний; физическое взаимодействие с изображением тоже выдаёт обман. Распознавшая цель воспринимает иллюзию как слабую. Повторное сотворение прекращает прежнюю иллюзию.","detailed_description":"Вы создаёте [thunder]:thunder:звук[/thunder] или изображение объекта в пределах дистанции на 1 минуту. Иллюзия исчезает, если вы снова сотворите это заклинание.\n\nСущество может [[действием|concept:action]] [[Изучение|concept:study]] исследовать [thunder]:thunder:звук[/thunder] или изображение и распознать иллюзию, преуспев в проверке Интеллекта (Расследование) против [[СЛ|concept:difficulty_class]] ваших заклинаний. Для распознавшего её существа иллюзия становится слабой.\n\n**[thunder]:thunder:Звук[/thunder].** Громкость может варьироваться от шёпота до крика. Это может быть ваш или чужой голос, рык льва, бой барабанов либо любой другой [thunder]:thunder:звук[/thunder]. [thunder]:thunder:Звук[/thunder] может непрерывно сохраняться всю длительность или раздаваться отдельно в выбранные моменты.\n\n**Изображение.** Вы создаёте изображение объекта, например стула, грязных следов или небольшого сундука, не больше [[Куба|concept:cube]] со стороной 5 футов. Оно не создаёт звука, света, запаха или других сенсорных эффектов. Физическое взаимодействие раскрывает иллюзию, поскольку предметы проходят сквозь изображение.","upcast_description":null},"expected_mechanics":{"activation":{"cast_time":{"amount":1,"unit":"action"},"cost":[{"resource":"action"}],"mode":"active"},"effects":[{"resolution":"auto","result":[{"description":"Малая иллюзия: см. описание заклинания.","kind":"narrative"}]}],"primitive":{"policy":{"duration_rounds":10,"image_max_cube_side_ft":5,"max_active_per_source":1,"study_ability":"int","study_skill":"investigation"},"type":"minor_illusion_world_object"},"spell_class_list_ids":["CLASS-bard","CLASS-sorcerer","CLASS-warlock","CLASS-wizard"],"targeting":{"actor_targets":false,"allowed_relations":[],"domain":"world","filter":"any","max_targets":1,"min_targets":0,"range":"30 футов","range_ft":30,"requires_line_of_sight":false,"shape":"single"}}},{"id":"f5d4b18f-6212-47e7-ae0b-8dda2f84d4c2","card_number":"SPELL-0224","name":"Меткий удар","before":{"description":"Руководствуясь вспышкой магической проницательности, вы совершаете одну атаку оружием, использованным при сотворении заклинания. Атака использует вашу заклинательную характеристику вместо Силы или Ловкости для бросков атаки и урона.\n\nЕсли атака наносит урон, это может быть урон [radiant]:radiant:Излучением [/radiant]или обычный урон от атаки этим оружием (по вашему выбору).","detailed_description":null,"upcast_description":"Независимо от того, наносите ли вы урон [radiant]:radiant:Излучением[/radiant] или обычным типом урона оружия, атака наносит дополнительный урон [radiant]Излучением[/radiant], когда вы достигаете 5‑го уровня (1к6), 11‑го уровня (2к6) и 17‑го уровня (3к6)."},"after":{"description":"Руководствуясь вспышкой магической проницательности, вы совершаете одну атаку оружием, использованным при сотворении заклинания. Атака использует вашу [[заклинательную характеристику|concept:ability_score_and_modifier]] вместо Силы или Ловкости для [[бросков атаки|concept:attack_roll]] и урона.\n\nЕсли атака наносит урон, это может быть урон [radiant]:radiant:Излучением [/radiant] или обычный урон от атаки этим оружием (по вашему выбору).","detailed_description":"Руководствуясь вспышкой магической проницательности, вы совершаете одну атаку оружием, использованным при сотворении заклинания. Атака использует вашу [[заклинательную характеристику|concept:ability_score_and_modifier]] вместо Силы или Ловкости для [[бросков атаки|concept:attack_roll]] и урона.\n\nЕсли атака наносит урон, это может быть урон [radiant]:radiant:Излучением [/radiant] или обычный урон от атаки этим оружием (по вашему выбору).","upcast_description":"Независимо от того, наносите ли вы урон [radiant]:radiant:Излучением[/radiant] или обычным типом урона оружия, атака наносит дополнительный урон [radiant]:radiant:Излучением[/radiant], когда вы достигаете 5‑го уровня (1к6), 11‑го уровня (2к6) и 17‑го уровня (3к6)."},"expected_mechanics":{"activation":{"cost":[{"resource":"action"}],"mode":"active"},"effects":[{"ability":"spellcasting","on_hit":[{"context":"in_play","count":1,"id":"true_strike_damage_type","kind":"choice","options":{"items":[{"grants":[{"ability":"spellcasting","dice":"weapon","kind":"damage","type":"weapon"},{"dice":"0","kind":"damage","omit_if_zero":true,"scaling":{"dice":"1d6","per":"character_level"},"suppress_damage_modifiers":true,"type":"radiant"}],"id":"weapon","name":"Обычный тип оружия"},{"grants":[{"ability":"spellcasting","dice":"weapon","kind":"damage","type":"radiant"},{"dice":"0","kind":"damage","omit_if_zero":true,"scaling":{"dice":"1d6","per":"character_level"},"suppress_damage_modifiers":true,"type":"radiant"}],"id":"radiant","name":"Излучение"}],"source":"explicit"},"prompt":"Выберите тип урона оружия"}],"resolution":"attack_roll","vs":"ac"}],"spell_class_list_ids":["CLASS-bard","CLASS-sorcerer","CLASS-warlock","CLASS-wizard"],"spell_variant_ids":["39400cef-bf13-50b6-a3c9-cf470dda1219","48f07634-634c-562c-a9c6-7e2e73cbb9d3"],"targeting":{"actor_targets":true,"allowed_relations":["enemy"],"domain":"actor","max_targets":1,"min_targets":1,"range_ft":600,"requires_line_of_sight":true,"shape":"single"}}},{"id":"0f0eca67-f241-4f1a-b01b-37c6f16adea2","card_number":"SPELL-0226","name":"Мистический заряд","before":{"description":"Вы выбрасываете луч потрескивающей энергии. Совершите дальнобойную [[атаку заклинанием|concept:spell_attack]] по одному существу или объекту в пределах дистанции. При попадании цель получает [force]1к10:force:чистой силой[/force].","detailed_description":null,"upcast_description":"Заклинание создаёт два луча на 5‑м уровне, три луча на 11‑м уровне и четыре луча на 17‑м уровне. Вы можете направить лучи в одну цель или в разных. Для каждого луча совершите свой [[бросок атаки|concept:attack_roll]]."},"after":{"description":"Вы выбрасываете луч потрескивающей энергии. Совершите дальнобойную [[атаку заклинанием|concept:spell_attack]] по одному существу или объекту в пределах дистанции. При попадании цель получает [force]1к10:force:чистой силой[/force].","detailed_description":"Вы выбрасываете луч потрескивающей энергии. Совершите дальнобойную [[атаку заклинанием|concept:spell_attack]] по одному существу или объекту в пределах дистанции. При попадании цель получает [force]1к10:force:чистой силой[/force].","upcast_description":"Заклинание создаёт два луча на 5‑м уровне, три луча на 11‑м уровне и четыре луча на 17‑м уровне. Вы можете направить лучи в одну цель или в разных. Для каждого луча совершите свой [[бросок атаки|concept:attack_roll]]."},"expected_mechanics":{"activation":{"cost":[{"resource":"action"}],"mode":"active"},"effects":[{"ability":"spellcasting","attack_kind":"spell_ranged","on_hit":[{"dice":"1d10","kind":"damage","type":"force"}],"resolution":"attack_roll","vs":"ac"}],"spell_class_list_ids":["CLASS-warlock"],"targeting":{"actor_targets":true,"allow_repeat_targets":true,"allowed_relations":["self","ally","enemy","neutral"],"domain":"actor","filter":"any","max_targets":1,"min_targets":1,"range":"120 футов","range_ft":120,"requires_line_of_sight":true,"shape":"multiple","target_slots_by_character_level":{"1":1,"5":2,"11":3,"17":4}}}},{"id":"70dcdadd-7e66-43f0-81b1-1fd1d346d9b7","card_number":"SPELL-0230","name":"Наставление","before":{"description":"Вы касаетесь согласного существа и выбираете навык. Пока заклинание активно, цель добавляет 1к4 к любой проверке характеристики, использующей выбранный навык.","detailed_description":null,"upcast_description":null},"after":{"description":"Вы касаетесь согласного существа и выбираете [[навык|concept:skill]]. Пока заклинание активно, цель добавляет 1к4 к любой [[проверке характеристики|concept:ability_check]], использующей выбранный навык.","detailed_description":"Вы касаетесь согласного существа и выбираете [[навык|concept:skill]]. Пока заклинание активно, цель добавляет 1к4 к любой [[проверке характеристики|concept:ability_check]], использующей выбранный навык.","upcast_description":null},"expected_mechanics":{"activation":{"cast_time":{"amount":1,"unit":"action"},"cost":[{"resource":"action"}],"mode":"active"},"effects":[{"context":"in_play","count":1,"id":"guidance_skill","kind":"choice","options":{"items":[{"grants":[{"kind":"grant_effect","value":"EFFECT-runtime-d13a43d7c5f6db943159"}],"id":"acrobatics","name":"Акробатика"},{"grants":[{"kind":"grant_effect","value":"EFFECT-runtime-9e53e5140f0f97c3926f"}],"id":"animal_handling","name":"Уход за животными"},{"grants":[{"kind":"grant_effect","value":"EFFECT-runtime-d5e46720dbe9d26bea2a"}],"id":"arcana","name":"Магия"},{"grants":[{"kind":"grant_effect","value":"EFFECT-runtime-711ae809997096ee19fa"}],"id":"athletics","name":"Атлетика"},{"grants":[{"kind":"grant_effect","value":"EFFECT-runtime-4a78ea35202dfc96fedb"}],"id":"deception","name":"Обман"},{"grants":[{"kind":"grant_effect","value":"EFFECT-runtime-02ad7f662404f72bdc2e"}],"id":"history","name":"История"},{"grants":[{"kind":"grant_effect","value":"EFFECT-runtime-320f7b0d131c7a9b9b64"}],"id":"insight","name":"Проницательность"},{"grants":[{"kind":"grant_effect","value":"EFFECT-runtime-985b255ed7c256d09c34"}],"id":"intimidation","name":"Запугивание"},{"grants":[{"kind":"grant_effect","value":"EFFECT-runtime-ade60ced2002453f965c"}],"id":"investigation","name":"Расследование"},{"grants":[{"kind":"grant_effect","value":"EFFECT-runtime-231ec5ffda57a5e275dd"}],"id":"medicine","name":"Медицина"},{"grants":[{"kind":"grant_effect","value":"EFFECT-runtime-af798f91b621a0b0390f"}],"id":"nature","name":"Природа"},{"grants":[{"kind":"grant_effect","value":"EFFECT-runtime-356150dad7541168eca1"}],"id":"perception","name":"Восприятие"},{"grants":[{"kind":"grant_effect","value":"EFFECT-runtime-a9d5d658a820c96ad77d"}],"id":"performance","name":"Выступление"},{"grants":[{"kind":"grant_effect","value":"EFFECT-runtime-dd9aaaa99544838493a7"}],"id":"persuasion","name":"Убеждение"},{"grants":[{"kind":"grant_effect","value":"EFFECT-runtime-4065d37fbed748da9203"}],"id":"religion","name":"Религия"},{"grants":[{"kind":"grant_effect","value":"EFFECT-runtime-123f8c387cd4d2e10d7b"}],"id":"sleight_of_hand","name":"Ловкость рук"},{"grants":[{"kind":"grant_effect","value":"EFFECT-runtime-13e373db1df54f3cf6e5"}],"id":"stealth","name":"Скрытность"},{"grants":[{"kind":"grant_effect","value":"EFFECT-runtime-dbce0f885b9a3a7eebfb"}],"id":"survival","name":"Выживание"}],"source":"explicit"},"prompt":"Выберите навык для Наставления","resolution":"immediate","who":"target"}],"spell_class_list_ids":["CLASS-cleric","CLASS-druid"],"spell_variant_ids":["8147c9f6-bd43-50bb-ad1b-01d743908448","cfa10828-bdd6-56df-ad9e-4f3d5d0e76ba","ecdf1283-2502-5020-a519-93d3eb6256d4","542c18e6-3fa0-5c48-af17-838c91038a32","13f6c6d9-0210-5762-a9c6-01cd17d55bcc","72138e78-30bb-5168-a675-3756cf794729","0a279ad1-5550-58ab-a228-e399338babcf","9d02f061-7ec1-5fc5-a864-9cc5628c0f3e","e751f556-e126-5fb0-a80c-3a475c3b89f3","98bf10f9-89a9-5f82-aff0-0fd2d82ff619","d1097558-c304-5031-a3e6-ce64823e3b1d","75ed8f25-6c75-5118-a600-550ffe73266c","6915159b-fda2-5bf6-a5d2-e1dd18f23879","44a42525-26d1-5131-ae52-57007fc85ae3","88507518-d783-5b87-aa5d-b12f17d7e32e","6d0575be-1c0d-5bbf-a303-0db0da313f06","08d508e6-e862-5434-a860-1a75137bb5ed","a6d69f47-121f-5925-a3f2-f1036e604752"],"targeting":{"actor_targets":true,"allowed_relations":["self","ally","enemy","neutral"],"domain":"actor","filter":"creature","max_targets":1,"min_targets":1,"range":"Касание","range_ft":5,"requires_line_of_sight":false,"requires_touch":true,"requires_willing":true,"shape":"single"}}},{"id":"50626b5a-33c5-46e0-af0e-50599f4306a0","card_number":"fire_bolt","name":"Огненный снаряд","before":{"description":"Вы кидаете сгусток огня в существо или объект в пределах дистанции.\nСовершите Дальнобойную [[атаку заклинанием|concept:spell_attack]] по цели.\nПри попадании цель получает [fire]1к10:fire:огнём[/fire]. Горючие объекты, по которым попало это заклинание, воспламеняются, если их никто не несёт и не носит.","detailed_description":null,"upcast_description":"Урон увеличивается на 1к10, когда вы достигаете 5‑го уровня (2к10), 11‑го уровня (3к10) и 17‑го уровня (4к10)."},"after":{"description":"Вы метаете сгусток огня в существо или объект в пределах дистанции. Совершите дальнобойную [[атаку заклинанием|concept:spell_attack]] по цели. При попадании цель получает [fire]1к10 :fire:урона огнём[/fire].\n\nГорючий объект, в который попало заклинание, загорается, если его никто не носит и не несёт.","detailed_description":"Вы метаете сгусток огня в существо или объект в пределах дистанции. Совершите дальнобойную [[атаку заклинанием|concept:spell_attack]] по цели. При попадании цель получает [fire]1к10 :fire:урона огнём[/fire].\n\nГорючий объект, в который попало заклинание, загорается, если его никто не носит и не несёт.","upcast_description":"Урон увеличивается на 1к10, когда вы достигаете 5‑го уровня (2к10), 11‑го уровня (3к10) и 17‑го уровня (4к10)."},"expected_mechanics":{"activation":{"cast_time":{"amount":1,"unit":"action"},"cost":[{"resource":"action"}],"mode":"active"},"effects":[{"ability":"spellcasting","attack_kind":"spell_ranged","on_hit":[{"dice":"1d10","kind":"damage","scaling":{"dice":"1d10","per":"character_level"},"type":"fire"}],"resolution":"attack_roll","vs":"ac"}],"interaction":{"intent":"harmful"},"spell_class_list_ids":["CLASS-sorcerer","CLASS-wizard"],"targeting":{"actor_targets":true,"allowed_relations":["self","ally","enemy","neutral"],"domain":"mixed","filter":"any","max_targets":1,"min_targets":1,"range":"120 футов","range_ft":120,"requires_line_of_sight":true,"shape":"single"}}},{"id":"b2c5ebf4-facc-4521-948f-55b30746bfa5","card_number":"dancing_lights","name":"Пляшущие огоньки","before":{"description":"Вы создаёте не более четырёх огоньков размером с факел в пределах дистанции, делая их похожими на факелы, фонари или светящиеся сферы, парящие в воздухе. В качестве альтернативы вы можете объединить четыре огонька в одну светящуюся Среднюю человекоподобную фигуру.","detailed_description":"Вы создаёте не более четырёх огоньков размером с факел в пределах дистанции, делая их похожими на факелы, фонари или светящиеся сферы, парящие в воздухе. В качестве альтернативы вы можете объединить четыре огонька в одну светящуюся Среднюю человекоподобную фигуру. Какую бы форму вы ни выбрали, каждый огонёк излучает [[Тусклый свет|concept:dim_light]] в пределах 10 футов.\n\nВы можете :bonus_action:Бонусным действием в свой ход переместить огоньки на расстояние не более 60 футов в новое место в пределах дистанции. Каждый огонёк должен находиться в пределах 20 футов от другого огонька, созданного этим заклинанием, и огонёк тухнет, если оказывается за пределами дистанции заклинания.","upcast_description":null},"after":{"description":"Создайте до четырёх огоньков или одну Среднюю человекоподобную светящуюся фигуру. Каждый огонёк даёт [[Тусклый свет|concept:dim_light]] в радиусе 10 футов. [[Бонусным действием|concept:bonus_action]] можно переместить огоньки до 60 футов в пределах дистанции. Огоньки должны оставаться в пределах 20 футов друг от друга; за пределами дистанции они исчезают.","detailed_description":"Вы создаёте не более четырёх огоньков размером с факел в пределах дистанции, делая их похожими на факелы, фонари или светящиеся сферы, парящие в воздухе. В качестве альтернативы вы можете объединить четыре огонька в одну светящуюся Среднюю человекоподобную фигуру. Какую бы форму вы ни выбрали, каждый огонёк излучает [[Тусклый свет|concept:dim_light]] в пределах 10 футов.\n\nВы можете :bonus_action:[[Бонусным действием|concept:bonus_action]] в свой ход переместить огоньки на расстояние не более 60 футов в новое место в пределах дистанции. Каждый огонёк должен находиться в пределах 20 футов от другого огонька, созданного этим заклинанием, и огонёк тухнет, если оказывается за пределами дистанции заклинания.","upcast_description":null},"expected_mechanics":{"activation":{"cast_time":{"amount":1,"unit":"action"},"cost":[{"resource":"action"}],"mode":"active"},"effects":[{"resolution":"auto","result":[]}],"primitive":{"policy":{"combined_form_object_count":1,"dim_radius_ft":10,"duration_rounds":10,"max_individual_lights":4,"max_move_ft":60,"min_individual_lights":1,"required_separation_ft":20},"type":"dancing_lights_world"},"spell_class_list_ids":["CLASS-bard","CLASS-sorcerer","CLASS-wizard"],"targeting":{"actor_targets":false,"allowed_relations":[],"domain":"world","filter":"any","max_targets":1,"min_targets":0,"range":"120 футов","range_ft":120,"requires_line_of_sight":false,"shape":"multiple"}}},{"id":"a9a0d114-ad46-435e-a3c9-128b305b8a5d","card_number":"SPELL-0260","name":"Погребальный звон","before":{"description":"Вы указываете на одно существо, которое можете видеть в пределах дистанции, и одиночный скорбный звук колокола слышен в пределах 10 футов от цели. Цель должна преуспеть в спасброске Мудрости, иначе получит [necrotic]1к8:necrotic:некротической энергией[/necrotic].\n\nЕсли [[Хиты|concept:hit_points]] цели неполные, то вместо этого она получает [necrotic]1к12:necrotic:некротической энергией[/necrotic].","detailed_description":null,"upcast_description":"Урон увеличивается на одну кость, когда вы достигаете 5‑го уровня (2к8 или 2к12), 11‑го уровня (3к8 или 3к12) и 17‑го уровня (4к8 или 4к12). Такие заклинания, как Подводное дыхание и Хождение по воде, помогают посещать водные царства"},"after":{"description":"Вы указываете на одно существо, которое можете видеть в пределах дистанции, и одиночный скорбный [thunder]:thunder:звук[/thunder] колокола слышен в пределах 10 футов от цели. Цель должна преуспеть в [[спасброске|concept:saving_throw_]] Мудрости, иначе получит [necrotic]1к8:necrotic:некротической энергией[/necrotic].\n\nЕсли [[Хиты|concept:hit_points]] цели неполные, то вместо этого она получает [necrotic]1к12:necrotic:некротической энергией[/necrotic].","detailed_description":"Вы указываете на одно существо, которое можете видеть в пределах дистанции, и одиночный скорбный [thunder]:thunder:звук[/thunder] колокола слышен в пределах 10 футов от цели. Цель должна преуспеть в [[спасброске|concept:saving_throw_]] Мудрости, иначе получит [necrotic]1к8:necrotic:некротической энергией[/necrotic].\n\nЕсли [[Хиты|concept:hit_points]] цели неполные, то вместо этого она получает [necrotic]1к12:necrotic:некротической энергией[/necrotic].","upcast_description":"Урон увеличивается на одну кость на 5-м уровне (2к8 или 2к12), 11-м уровне (3к8 или 3к12) и 17-м уровне (4к8 или 4к12)."},"expected_mechanics":{"activation":{"cost":[{"resource":"action"}],"mode":"active"},"effects":[{"ability":"wis","dc":"8 + prof + spellcasting","on_fail":[{"dice":"1d8","kind":"damage","scaling":{"dice":"1d8","per":"character_level"},"type":"necrotic","when":[{"kind":"not","of":{"kind":"target_hp_fraction_below","value":1}}]},{"dice":"1d12","kind":"damage","scaling":{"dice":"1d12","per":"character_level"},"type":"necrotic","when":[{"kind":"target_hp_fraction_below","value":1}]}],"on_success":[],"resolution":"save","who":"target"}],"spell_class_list_ids":["CLASS-cleric","CLASS-warlock","CLASS-wizard"],"targeting":{"actor_targets":true,"allowed_relations":["self","ally","enemy","neutral"],"domain":"actor","filter":"any","max_targets":1,"min_targets":1,"range":"60 футов","range_ft":60,"requires_line_of_sight":true,"requires_sight":true,"shape":"single"}}},{"id":"5b79a37b-e7a9-482a-9efc-46b57e3a79de","card_number":"mending","name":"Починка","before":{"description":"Это заклинание чинит одно повреждение или разрыв на объекте, которого касаетесь, например, разорванное звено цепи, две половинки сломанного ключа, порванный плащ или протекающий бурдюк. Если повреждение или разрыв не больше 1 фута в длину, вы чините его, не оставляя следов.\n\nЭто заклинание может физически починить магический предмет, но не может восстановить магию в таком объекте.","detailed_description":null,"upcast_description":null},"after":{"description":"Заклинание чинит одно повреждение или разрыв на объекте, которого вы касаетесь: например, разорванное звено цепи, две половинки сломанного ключа, порванный плащ или протекающий бурдюк. Если повреждение или разрыв не превышает 1 фута ни в одном измерении, вы чините его без следов прежнего повреждения.\n\nЗаклинание может физически починить магический предмет, но не восстанавливает его магию.","detailed_description":"Заклинание чинит одно повреждение или разрыв на объекте, которого вы касаетесь: например, разорванное звено цепи, две половинки сломанного ключа, порванный плащ или протекающий бурдюк. Если повреждение или разрыв не превышает 1 фута ни в одном измерении, вы чините его без следов прежнего повреждения.\n\nЗаклинание может физически починить магический предмет, но не восстанавливает его магию.","upcast_description":null},"expected_mechanics":{"activation":{"cast_time":{"amount":1,"unit":"minute"},"cost":[{"resource":"action"}],"mode":"active"},"effects":[{"resolution":"auto","result":[]}],"primitive":{"policy":{"max_break_dimension_ft":1},"type":"mending_world"},"spell_class_list_ids":["CLASS-bard","CLASS-cleric","CLASS-druid","CLASS-sorcerer","CLASS-wizard"],"targeting":{"actor_targets":false,"allowed_relations":[],"domain":"world","filter":"any","max_targets":1,"min_targets":0,"range":"Касание","range_ft":0,"requires_line_of_sight":false,"requires_touch":true,"shape":"single"}}},{"id":"13e456fc-cf29-4c46-8aeb-c282a9cbcd5f","card_number":"SPELL-0280","name":"Раскат грома","before":{"description":"Каждое существо в исходящей от вас 5‑футовой Эманации должно преуспеть в спасброске Телосложения, иначе получит [thunder]1к6:thunder:звуком[/thunder]. Раскат грома от заклинания слышен на расстоянии не более 100 футов.","detailed_description":null,"upcast_description":"Урон увеличивается на 1к6, когда вы достигаете 5‑го уровня (2к6), 11‑го уровня (3к6) и 17‑го уровня (4к6)."},"after":{"description":"Каждое существо в исходящей от вас 5‑футовой [[Эманации|concept:emanation]] должно преуспеть в [[спасброске|concept:saving_throw_]] Телосложения, иначе получит [thunder]1к6:thunder:звуком[/thunder]. Раскат грома от заклинания слышен на расстоянии не более 100 футов.","detailed_description":"Каждое существо в исходящей от вас 5‑футовой [[Эманации|concept:emanation]] должно преуспеть в [[спасброске|concept:saving_throw_]] Телосложения, иначе получит [thunder]1к6:thunder:звуком[/thunder]. Раскат грома от заклинания слышен на расстоянии не более 100 футов.","upcast_description":"Урон увеличивается на 1к6, когда вы достигаете 5‑го уровня (2к6), 11‑го уровня (3к6) и 17‑го уровня (4к6)."},"expected_mechanics":{"activation":{"cost":[{"resource":"action"}],"mode":"active"},"effects":[{"ability":"con","dc":"8 + prof + spellcasting","on_fail":[{"dice":"1d6","kind":"damage","scaling":{"dice":"1d6","per":"character_level"},"type":"thunder"},{"description":"Звук слышен на расстоянии до 100 футов.","kind":"narrative"}],"on_success":[],"resolution":"save","who":"target"}],"spell_class_list_ids":["CLASS-bard","CLASS-druid","CLASS-sorcerer","CLASS-warlock","CLASS-wizard"],"targeting":{"actor_targets":true,"allowed_relations":["self","ally","enemy","neutral"],"area":{"kind":"emanation","radius_ft":5},"domain":"actor","max_targets":64,"min_targets":1,"range_ft":5,"requires_line_of_sight":false,"requires_touch":true,"shape":"area"}}},{"id":"c3fc969b-ba03-443f-a222-46f6b9a53bd6","card_number":"SPELL-0281","name":"Расщепление разума","before":{"description":"Вы пытаетесь временно расщепить разум одного существа, которое вы можете видеть в пределах дистанции. Цель должна преуспеть в спасброске Интеллекта, иначе получит [psychic]1к6:psychic:психической энергией[/psychic] и вычтет 1к4 из следующего [[спасброска|concept:saving_throw_]], совершаемого ею до конца вашего следующего хода.","detailed_description":null,"upcast_description":"Урон увеличивается на 1к6, когда вы достигаете 5‑го уровня (2к6), 11‑го уровня (3к6) и 17‑го уровня (4к6)."},"after":{"description":"Вы пытаетесь временно расщепить разум одного существа, которое вы можете видеть в пределах дистанции. Цель должна преуспеть в [[спасброске|concept:saving_throw_]] Интеллекта, иначе получит [psychic]1к6:psychic:психической энергией[/psychic] и вычтет 1к4 из следующего спасброска, совершаемого ею до конца вашего следующего хода.","detailed_description":"Вы пытаетесь временно расщепить разум одного существа, которое вы можете видеть в пределах дистанции. Цель должна преуспеть в [[спасброске|concept:saving_throw_]] Интеллекта, иначе получит [psychic]1к6:psychic:психической энергией[/psychic] и вычтет 1к4 из следующего спасброска, совершаемого ею до конца вашего следующего хода.","upcast_description":"Урон увеличивается на 1к6, когда вы достигаете 5‑го уровня (2к6), 11‑го уровня (3к6) и 17‑го уровня (4к6)."},"expected_mechanics":{"activation":{"cost":[{"resource":"action"}],"mode":"active"},"effects":[{"ability":"int","dc":"8 + prof + spellcasting","on_fail":[{"dice":"1d6","kind":"damage","scaling":{"dice":"1d6","per":"character_level"},"type":"psychic"},{"kind":"grant_effect","value":"EFFECT-runtime-178e5d1ea0aff2a19bb8"}],"on_success":[],"resolution":"save","who":"target"}],"spell_class_list_ids":["CLASS-sorcerer","CLASS-warlock","CLASS-wizard"],"targeting":{"filter":"any","range":"60 футов","shape":"single"}}},{"id":"1e9cb7db-f4dc-4215-ad57-0e3407b78913","card_number":"light","name":"Свет","before":{"description":"Вы касаетесь одного объекта Большого размера или меньше, который никто не носит и не несёт. Пока заклинание активно, объект испускает [[Яркий свет|concept:bright_light]] в пределах 20 футов и [[Тусклый свет|concept:dim_light]] в пределах ещё 20 футов. Свет может быть любого выбранного вами цвета. Полное покрытие предмета чем‑то непрозрачным блокирует свет.\n\nЗаклинание заканчивается, если вы сотворите его ещё раз.","detailed_description":null,"upcast_description":null},"after":{"description":"Вы касаетесь одного объекта Большого размера или меньше, который не носит и не несёт другое существо. Пока заклинание активно, объект испускает [[Яркий свет|concept:bright_light]] в радиусе 20 футов и [[Тусклый свет|concept:dim_light]] ещё на 20 футов. Цвет света вы выбираете.\n\nЕсли накрыть объект непрозрачным материалом, свет блокируется. Заклинание заканчивается, если вы сотворите его снова.\n\n**Материальный компонент.** Светлячок или фосфоресцирующий мох.","detailed_description":"Вы касаетесь одного объекта Большого размера или меньше, который не носит и не несёт другое существо. Пока заклинание активно, объект испускает [[Яркий свет|concept:bright_light]] в радиусе 20 футов и [[Тусклый свет|concept:dim_light]] ещё на 20 футов. Цвет света вы выбираете.\n\nЕсли накрыть объект непрозрачным материалом, свет блокируется. Заклинание заканчивается, если вы сотворите его снова.\n\n**Материальный компонент.** Светлячок или фосфоресцирующий мох.","upcast_description":null},"expected_mechanics":{"activation":{"cast_time":{"amount":1,"unit":"action"},"cost":[{"resource":"action"}],"mode":"active"},"effects":[{"resolution":"auto","result":[{"description":"Свет: см. описание заклинания.","kind":"narrative"}]}],"primitive":{"policy":{"bright_radius_ft":20,"dim_additional_radius_ft":20,"duration_rounds":600,"exclude_carried_by_other":true,"max_active_per_source":1,"max_object_size":"large"},"type":"light_world_object"},"spell_class_list_ids":["CLASS-bard","CLASS-cleric","CLASS-sorcerer","CLASS-wizard"],"targeting":{"actor_targets":false,"allowed_relations":[],"domain":"world","filter":"any","max_targets":1,"min_targets":0,"range":"Касание","range_ft":0,"requires_line_of_sight":false,"requires_touch":true,"shape":"single"}}},{"id":"8cddf152-e406-4c7a-8d34-cc8bcbfc0dfa","card_number":"SPELL-0286","name":"Священное пламя","before":{"description":"Похожее на огонь сияние нисходит на существо, которое вы можете видеть в пределах дистанции. Цель должна преуспеть в спасброске Ловкости, иначе получит [radiant]1к8:radiant:излучением[/radiant]. Цель не получает [[преимущества|concept:advantage]] от [[Укрытия|concept:cover]] на половину и Укрытия на три четверти к этому спасброску.","detailed_description":null,"upcast_description":"Урон заклинания увеличивается на 1к8, когда вы достигаете 5‑го уровня (2к8), 11‑го уровня (3к8) и 17‑го уровня (4к8)."},"after":{"description":"Похожее на пламя сияние нисходит на видимое вами существо в пределах дистанции. Цель совершает [[спасбросок|concept:saving_throw_]] Ловкости и при провале получает [radiant]1к8 :radiant:урона излучением[/radiant].\n\nЦель не получает бонусов от [[укрытия|concept:cover]] на половину или на три четверти к этому спасброску.","detailed_description":"Похожее на пламя сияние нисходит на видимое вами существо в пределах дистанции. Цель совершает [[спасбросок|concept:saving_throw_]] Ловкости и при провале получает [radiant]1к8 :radiant:урона излучением[/radiant].\n\nЦель не получает бонусов от [[укрытия|concept:cover]] на половину или на три четверти к этому спасброску.","upcast_description":"Урон заклинания увеличивается на 1к8, когда вы достигаете 5‑го уровня (2к8), 11‑го уровня (3к8) и 17‑го уровня (4к8)."},"expected_mechanics":{"activation":{"cast_time":{"amount":1,"unit":"action"},"cost":[{"resource":"action"}],"mode":"active"},"effects":[{"ability":"dex","dc":"8 + prof + spellcasting","on_fail":[{"dice":"1d8","kind":"damage","scaling":{"dice":"1d8","per":"character_level"},"type":"radiant"}],"on_success":[],"resolution":"save","who":"target"}],"interaction":{"intent":"harmful"},"spell_class_list_ids":["CLASS-cleric"],"targeting":{"actor_targets":true,"allowed_relations":["self","ally","enemy","neutral"],"domain":"actor","filter":"any","max_targets":1,"min_targets":1,"range":"60 футов","range_ft":60,"requires_line_of_sight":true,"requires_sight":true,"shape":"single"}}},{"id":"78eb6e5c-5d2a-42ad-8e6e-6bf3be3f96c0","card_number":"SPELL-0291","name":"Слово сияния","before":{"description":"Из вас извергается жгучее сияние 5‑футовой Эманацией. Каждое существо по вашему выбору, которое вы можете видеть, должно преуспеть в спасброске Телосложения, иначе получит [radiant]1к6:radiant:излучением[/radiant].","detailed_description":null,"upcast_description":"Урон увеличивается на 1к6, когда вы достигаете 5‑го уровня (2к6), 11‑го уровня (3к6) и 17‑го уровня (4к6)."},"after":{"description":"Из вас извергается жгучее сияние 5‑футовой [[Эманацией|concept:emanation]]. Каждое существо по вашему выбору, которое вы можете видеть, должно преуспеть в [[спасброске|concept:saving_throw_]] Телосложения, иначе получит [radiant]1к6:radiant:излучением[/radiant].","detailed_description":"Из вас извергается жгучее сияние 5‑футовой [[Эманацией|concept:emanation]]. Каждое существо по вашему выбору, которое вы можете видеть, должно преуспеть в [[спасброске|concept:saving_throw_]] Телосложения, иначе получит [radiant]1к6:radiant:излучением[/radiant].","upcast_description":"Урон увеличивается на 1к6, когда вы достигаете 5‑го уровня (2к6), 11‑го уровня (3к6) и 17‑го уровня (4к6)."},"expected_mechanics":{"activation":{"cost":[{"resource":"action"}],"mode":"active"},"effects":[{"ability":"con","dc":"8 + prof + spellcasting","on_fail":[{"dice":"1d6","kind":"damage","scaling":{"dice":"1d6","per":"character_level"},"type":"radiant"}],"on_success":[],"resolution":"save","who":"target"}],"spell_class_list_ids":["CLASS-cleric"],"targeting":{"actor_targets":true,"allowed_relations":["self","ally","enemy","neutral"],"area":{"kind":"emanation","radius_ft":5},"domain":"actor","max_targets":64,"min_targets":1,"range_ft":5,"requires_line_of_sight":false,"requires_touch":true,"shape":"area"}}},{"id":"35d36558-8a47-49a1-9099-387bee37b8a2","card_number":"SPELL-0294","name":"Сообщение","before":{"description":"Вы указываете на существо в пределах дистанции и шепчете послание. Цель (и только цель) слышит его и может ответить шёпотом, который услышите только вы. Вы можете сотворять это заклинание сквозь твёрдые препятствия, если знакомы с целью и знаете, что она находится за барьером.\n\nМагическая тишина, 1 фут камня, металла или дерева, либо тонкий лист свинца или свинцовые блоки блокируют заклинание.","detailed_description":null,"upcast_description":null},"after":{"description":"Вы указываете на существо в пределах дистанции и шепчете сообщение. Только цель слышит его и может ответить шёпотом, который услышите только вы.\n\nЗаклинание проходит сквозь твёрдые препятствия, если вы знакомы с целью и знаете, что она находится за барьером. Магическая тишина, 1 фут камня, металла или дерева либо тонкий лист свинца блокируют заклинание.","detailed_description":"Вы указываете на существо в пределах дистанции и шепчете сообщение. Только цель слышит его и может ответить шёпотом, который услышите только вы.\n\nЗаклинание проходит сквозь твёрдые препятствия, если вы знакомы с целью и знаете, что она находится за барьером. Магическая тишина, 1 фут камня, металла или дерева либо тонкий лист свинца блокируют заклинание.","upcast_description":null},"expected_mechanics":{"activation":{"cost":[{"resource":"action"}],"mode":"active"},"effects":[{"resolution":"auto","result":[{"kind":"grant_effect","value":"EFFECT-runtime-540b081e1447e48d4d34"},{"description":"Доставка и ответ типизированы; знакомство с целью и фактический материал препятствия должны быть объявлены адаптером сцены.","kind":"narrative"}],"who":"target"}],"spell_class_list_ids":["CLASS-bard","CLASS-druid","CLASS-sorcerer","CLASS-wizard"],"targeting":{"actor_targets":true,"allowed_relations":["self","ally","enemy","neutral"],"domain":"actor","max_targets":1,"min_targets":1,"range_ft":120,"requires_line_of_sight":false,"shape":"single"}}},{"id":"bd99466f-46ab-4af5-a41d-b2b804b9f1e3","card_number":"SPELL-0295","name":"Сопротивление","before":{"description":"Вы касаетесь одного согласного существа. Оно получает [[устойчивость|concept:resistance]] к одному типу урона на ваш выбор.","detailed_description":"Вы касаетесь одного согласного существа и выбираете тип урона:\n:bludgeoning:Дробящий, [thunder]:thunder:Звук[/thunder], [radiant]:radiant:Излучение[/radiant],\n[acid]:acid:Кислота[/acid], :piercing:Колющий, [necrotic]:necrotic:Некротическая энергия[/necrotic], [fire]:fire:Огонь[/fire], :slashing:Рубящий,\n[cold]:cold:Холод[/cold], [lightning]:lightning:Электричество [/lightning]или [poison]:poison:Яд[/poison].\n\nКогда существо получает урон выбранного типа до окончания действия заклинания, оно уменьшает полученный урон на 1к4. Существо может получить [[преимущество|concept:advantage]] от этого заклинания только __один раз за ход__.","upcast_description":null},"after":{"description":"Коснитесь согласного существа и выберите один из 11 предусмотренных типов урона. До окончания [[концентрации|concept:concentration]], вплоть до 1 минуты, существо уменьшает получаемый урон этого типа на 1к4. Это уменьшение можно получить только один раз за ход.","detailed_description":"Вы касаетесь согласного существа и выбираете один тип урона: [acid]:acid:Кислота[/acid], [bludgeoning]:bludgeoning:Дробящий[/bludgeoning], [cold]:cold:Холод[/cold], [fire]:fire:Огонь[/fire], [lightning]:lightning:Электричество[/lightning], [necrotic]:necrotic:Некротическая энергия[/necrotic], [piercing]:piercing:Колющий[/piercing], [poison]:poison:Яд[/poison], [radiant]:radiant:Излучение[/radiant], [slashing]:slashing:Рубящий[/slashing] или [thunder]:thunder:Звук[/thunder].\n\nДо окончания заклинания, когда существо получает урон выбранного типа, оно уменьшает общий полученный урон на 1к4. Существо может воспользоваться этим уменьшением только один раз за ход.","upcast_description":null},"expected_mechanics":{"activation":{"cost":[{"resource":"action"}],"mode":"active"},"effects":[{"resolution":"auto","result":[{"context":"in_play","count":1,"id":"resistance_damage_type","kind":"choice","options":{"items":[{"grants":[{"kind":"grant_effect","value":"EFFECT-runtime-d768b314d8001a56b791"}],"id":"acid","name":"Кислота"},{"grants":[{"kind":"grant_effect","value":"EFFECT-runtime-441ad168295cd743b9a1"}],"id":"bludgeoning","name":"Дробящий"},{"grants":[{"kind":"grant_effect","value":"EFFECT-runtime-cf0074440959c50cff75"}],"id":"cold","name":"Холод"},{"grants":[{"kind":"grant_effect","value":"EFFECT-runtime-c692a5be4075adb6b578"}],"id":"fire","name":"Огонь"},{"grants":[{"kind":"grant_effect","value":"EFFECT-runtime-2c06dc519d73b15c0019"}],"id":"lightning","name":"Молния"},{"grants":[{"kind":"grant_effect","value":"EFFECT-runtime-e10368ce27c29b223766"}],"id":"necrotic","name":"Некротический"},{"grants":[{"kind":"grant_effect","value":"EFFECT-runtime-3678ca85117b4d3bdd2c"}],"id":"piercing","name":"Колющий"},{"grants":[{"kind":"grant_effect","value":"EFFECT-runtime-ccd0a094ea2053db0575"}],"id":"poison","name":"Яд"},{"grants":[{"kind":"grant_effect","value":"EFFECT-runtime-03651bededcb81e142cc"}],"id":"radiant","name":"Излучение"},{"grants":[{"kind":"grant_effect","value":"EFFECT-runtime-a923816229ada89036cb"}],"id":"slashing","name":"Рубящий"},{"grants":[{"kind":"grant_effect","value":"EFFECT-runtime-f6d7502b18abbc7f2a22"}],"id":"thunder","name":"Гром"}],"source":"explicit"},"prompt":"Выберите тип урона"}],"who":"target"}],"spell_class_list_ids":["CLASS-cleric","CLASS-druid"],"spell_variant_ids":["08f4c37f-980a-590a-a0e5-4e62e323e481","be19a61e-0211-54fc-a0c3-d50c16fffc4f","36259a69-93ba-5cc5-a537-425a8a2cc23f","3865ca56-0441-55e9-a9ce-88040b0fdae2","97535295-7d5d-5f99-a2b1-88113829a7ca","21de53ce-4dbb-556b-a84a-fe259ad6d5fe","634b6e23-8df5-54cb-afeb-92d1dca9f0df","4c77e278-5d20-5fde-a269-4a5fdd81cc4f","0268d1de-8593-536d-aa12-7530cbac9243","554a002c-5736-5c9e-a01c-1a063fc28c39","5ec6b2d4-587e-501f-ab09-0a175a591828"],"targeting":{"actor_targets":true,"allowed_relations":["self","ally"],"domain":"actor","max_targets":1,"min_targets":1,"range_ft":5,"requires_line_of_sight":false,"requires_touch":true,"shape":"single"}}},{"id":"ba23242c-eb9c-46a6-ba01-ebdc3b5b9618","card_number":"SPELL-0297","name":"Сотворение пламени","before":{"description":"В вашей ладони появляется мерцающее пламя и остаётся там, пока заклинание активно. Будучи на ладони, пламя не излучает тепла, ничего не поджигает и испускает [[Яркий свет|concept:bright_light]] в пределах 20 футов, а также [[Тусклый свет|concept:dim_light]] в пределах ещё 20 футов.","detailed_description":"В вашей ладони появляется мерцающее пламя и остаётся там, пока заклинание активно. Будучи на ладони, пламя не излучает тепла, ничего не поджигает и испускает [[Яркий свет|concept:bright_light]] в пределах 20 футов, а также [[Тусклый свет|concept:dim_light]] в пределах ещё 20 футов. Заклинание заканчивается, если вы сотворите его ещё раз.\n\nПока заклинание активно, вы можете :action:действием Магия метнуть пламя в существо или объект в пределах 60 футов. Совершите дальнобойную [[атаку заклинанием|concept:spell_attack]]. При попадании цель получает [fire]1к8:fire:огнём[/fire].","upcast_description":"Урон заклинания увеличивается на 1к8, когда вы достигаете 5‑го уровня (2к8), 11‑го уровня (3к8) и 17‑го уровня (4к8)."},"after":{"description":"[[Бонусным действием|concept:bonus_action]] создайте пламя в ладони на 10 минут: оно не греет и не поджигает, даёт [[Яркий свет|concept:bright_light]] на 20 футов и [[Тусклый свет|concept:dim_light]] ещё на 20 футов. Пока заклинание активно, [[действием|concept:action]] [[Магия|concept:magic]] можно метать [fire]:fire:огонь[/fire] в существо или объект до 60 футов: дальнобойная [[атака заклинанием|concept:spell_attack]] наносит [fire]1к8 :fire:урона огнём[/fire]. Повторное сотворение прекращает прежнее заклинание.","detailed_description":"В вашей ладони появляется мерцающее пламя и остаётся там, пока заклинание активно. Будучи на ладони, пламя не излучает тепла, ничего не поджигает и испускает [[Яркий свет|concept:bright_light]] в пределах 20 футов, а также [[Тусклый свет|concept:dim_light]] в пределах ещё 20 футов. Заклинание заканчивается, если вы сотворите его ещё раз.\n\nПока заклинание активно, вы можете :action:[[действием|concept:action]] [[Магия|concept:magic]] метнуть пламя в существо или объект в пределах 60 футов. Совершите дальнобойную [[атаку заклинанием|concept:spell_attack]]. При попадании цель получает [fire]1к8:fire:огнём[/fire].","upcast_description":"Урон заклинания увеличивается на 1к8, когда вы достигаете 5‑го уровня (2к8), 11‑го уровня (3к8) и 17‑го уровня (4к8)."},"expected_mechanics":{"activation":{"cost":[{"resource":"bonus_action"}],"mode":"active"},"effects":[{"resolution":"auto","result":[{"bind_action_context":true,"duration":{"amount":100,"type":"rounds"},"kind":"grant_effect","value":"EFFECT-spell-audit-produce-flame"}],"who":"self"}],"spell_class_list_ids":["CLASS-druid"],"targeting":{"actor_targets":false,"allowed_relations":["self"],"domain":"actor","max_targets":1,"min_targets":0,"range_ft":0,"requires_line_of_sight":false,"shape":"self"}}},{"id":"b84d904f-4768-4a05-8803-7a0d0da28a00","card_number":"SPELL-0298","name":"Стихийность","before":{"description":"Вы управляете стихиями, и можете создать один из эффектов, связанный с конкретной стихией: огнём, воздухом, водой или землёй.","detailed_description":"Вы управляете стихиями, создавая один из нижеперечисленных эффектов в пределах дистанции. Подманить воздух. Вы создаёте ветерок, достаточно сильный, чтобы колыхать ткань, ворошить пыль, шуршать листьями и закрывать открытые двери и ставни — всё в Кубе со стороной 5 футов.\n\nДвери и ставни, которые кто‑то или что‑то держит, не попадают под действие эффекта. Подманить землю. Вы создаёте тонкий слой из пыли или песка, который укрывает поверхности в квадрате со стороной 5 футов, либо заставляете одно слово, написанное вашим почерком, появиться на небольшом участке грязи или песка. Подманить огонь.\n\nВы создаёте тонкое облако безвредных искр и цветного ароматного дыма в Кубе со стороной 5 футов. Вы выбираете цвет и аромат, и искры могут зажигать свечи, факелы или лампы в области действия. Аромат дыма сохраняется в течение 1 минуты. Подманить воду.\n\nВы создаёте струю прохладного тумана, который слегка увлажняет существ и объекты в Кубе со стороной 5 футов. В качестве альтернативы вы создаёте 1 стакан чистой воды либо в открытой ёмкости, либо на поверхности, и эта вода испаряется через 1 минуту. Вылепить стихию.\n\nВы заставляете грязь, песок, огонь, дым, туман или воду, которые могут поместиться в Куб со стороной 1 фут, принять грубую форму (например, существа) на 1 час.","upcast_description":null},"after":{"description":"Создайте один небольшой эффект: ветерок, пыль или слово на земле, искры и ароматный дым, водяной туман или стакан воды. Либо придайте стихии в [[Кубе|concept:cube]] со стороной 1 фут грубую форму на 1 час.","detailed_description":"Вы создаёте один из следующих эффектов в пределах дистанции.\n\n**Подманить воздух.** В [[Кубе|concept:cube]] со стороной 5 футов ветерок колышет ткань, ворошит пыль, шуршит листьями и закрывает открытые двери и ставни. Удерживаемые кем-то или чем-то двери и ставни не затрагиваются.\n\n**Подманить землю.** Вы покрываете поверхности в квадрате со стороной 5 футов тонким слоем пыли или песка либо создаёте одно слово своим почерком на участке земли или песка.\n\n**Подманить [fire]:fire:огонь[/fire].** В Кубе со стороной 5 футов появляются безвредные искры и цветной ароматный дым. Вы выбираете цвет и аромат. Искры могут зажечь свечи, факелы или лампы в области. Аромат сохраняется 1 минуту.\n\n**Подманить воду.** Прохладный туман слегка увлажняет существ и объекты в Кубе со стороной 5 футов. Вместо этого вы можете создать один стакан чистой воды в открытой ёмкости или на поверхности; вода испаряется через 1 минуту.\n\n**Вылепить стихию.** Вы придаёте грязи, песку, огню, дыму, туману или воде, помещающимся в Куб со стороной 1 фут, грубую форму, например существа. Форма сохраняется 1 час.","upcast_description":null},"expected_mechanics":{"activation":{"cost":[{"resource":"action"}],"mode":"active"},"effects":[{"context":"in_play","count":1,"id":"elementalism_effect","kind":"choice","options":{"items":[{"grants":[{"kind":"world_interaction","operation":"beckon_air","parameters":{"area_shape":"cube","area_size_ft":5,"may_close_unheld_openings":true}}],"id":"air","name":"Призыв воздуха"},{"grants":[{"kind":"world_interaction","operation":"beckon_earth","parameters":{"area_shape":"square","area_size_ft":5,"may_write_single_word":true}}],"id":"earth","name":"Призыв земли"},{"grants":[{"kind":"world_interaction","operation":"beckon_fire","parameters":{"area_shape":"cube","area_size_ft":5,"harmless":true,"may_light_small_flames":true,"scent_duration_rounds":10}}],"id":"fire","name":"Призыв огня"},{"grants":[{"kind":"world_interaction","operation":"beckon_water","parameters":{"area_shape":"cube","area_size_ft":5,"created_water_cups":1,"created_water_duration_rounds":10}}],"id":"water","name":"Призыв воды"},{"grants":[{"kind":"world_interaction","operation":"sculpt_element","parameters":{"duration_rounds":600,"max_cube_ft":1,"shape_quality":"crude"}}],"id":"sculpt","name":"Ваяние стихии"}],"source":"explicit"},"prompt":"Выберите стихийный эффект"},{"resolution":"auto","result":[{"description":"Движок выдаёт типизированную мутацию окружения; её визуальное применение к объектам карты остаётся обязанностью world adapter.","kind":"narrative"}]}],"spell_class_list_ids":["CLASS-druid","CLASS-sorcerer","CLASS-wizard"],"spell_variant_ids":["a87f09ed-536d-5530-ab0b-cb4fb5dddbc8","554cdc1f-a23f-559d-aed4-c8338c75ee4c","5b149d6e-f0e4-5e4c-a300-675d2b90f343","2385cc5f-2ca9-571b-a78c-04670c59771c","213f9e6a-6000-5aac-accb-ae7f98588a7d"],"targeting":{"actor_targets":false,"allowed_relations":[],"domain":"world","max_targets":1,"min_targets":0,"range_ft":30,"requires_line_of_sight":true,"shape":"single"}}},{"id":"1c966901-b84a-435c-8950-1da774d72210","card_number":"SPELL-0300","name":"Терновый кнут","before":{"description":"Вы создаёте похожий на лозу кнут, покрытый шипами, бьющий по вашей команде существо, находящееся в пределах дистанции. Совершите по цели рукопашную [[атаку заклинанием|concept:spell_attack]]. При попадании цель получает [piercing]1к6:piercing:колющего урона[/piercing], и если она Большая или меньше, вы можете подтянуть её к себе на расстояние не более 10 футов.","detailed_description":null,"upcast_description":"Урон увеличивается на 1к6, когда вы достигаете 5‑го уровня (2к6), 11‑го уровня (3к6) и 17‑го уровня (4к6)."},"after":{"description":"Вы создаёте похожий на лозу кнут, покрытый шипами, бьющий по вашей команде существо, находящееся в пределах дистанции. Совершите по цели рукопашную [[атаку заклинанием|concept:spell_attack]]. При попадании цель получает [piercing]1к6:piercing:колющего урона[/piercing], и если она Большая или меньше, вы можете подтянуть её к себе на расстояние не более 10 футов.","detailed_description":"Вы создаёте похожий на лозу кнут, покрытый шипами, бьющий по вашей команде существо, находящееся в пределах дистанции. Совершите по цели рукопашную [[атаку заклинанием|concept:spell_attack]]. При попадании цель получает [piercing]1к6:piercing:колющего урона[/piercing], и если она Большая или меньше, вы можете подтянуть её к себе на расстояние не более 10 футов.","upcast_description":"Урон увеличивается на 1к6, когда вы достигаете 5‑го уровня (2к6), 11‑го уровня (3к6) и 17‑го уровня (4к6)."},"expected_mechanics":{"activation":{"cost":[{"resource":"action"}],"mode":"active"},"effects":[{"ability":"spellcasting","attack_kind":"spell_melee","on_hit":[{"dice":"1d6","kind":"damage","scaling":{"dice":"1d6","per":"character_level"},"type":"piercing"},{"distance":10,"kind":"movement","value":"pull"},{"description":"Притянуть можно цель Большого размера или меньше.","kind":"narrative"}],"resolution":"attack_roll","vs":"ac"}],"spell_class_list_ids":["CLASS-druid"],"targeting":{"filter":"any","range":"30 футов","shape":"single"}}},{"id":"d3177c17-b0c9-4691-a2ba-5ef24a28c1aa","card_number":"SPELL-0312","name":"Уход за умирающим","before":{"description":"Выберите живое существо, которое находится в пределах дистанции и имеет 0 [[Хитов|concept:hit_points]]. Существо становится Стабилизированным.","detailed_description":null,"upcast_description":"Дистанция удваивается, когда вы достигаете 5‑го уровня (30 футов), 11‑го уровня (60 футов) и 17‑го уровня (120 футов)."},"after":{"description":"Выберите существо в пределах дистанции, у которого 0 [[Хитов|concept:hit_points]] и которое не мертво. Существо становится [[Стабилизированным|concept:stable]].","detailed_description":"Выберите существо в пределах дистанции, у которого 0 [[Хитов|concept:hit_points]] и которое не мертво. Существо становится [[Стабилизированным|concept:stable]].","upcast_description":"Дистанция удваивается, когда вы достигаете 5‑го уровня (30 футов), 11‑го уровня (60 футов) и 17‑го уровня (120 футов)."},"expected_mechanics":{"activation":{"cost":[{"resource":"action"}],"mode":"active"},"effects":[{"resolution":"auto","result":[{"kind":"stabilize"}],"who":"target"}],"spell_class_list_ids":["CLASS-cleric","CLASS-druid"],"targeting":{"actor_targets":true,"allowed_relations":["self","ally","neutral"],"domain":"actor","max_targets":1,"min_targets":1,"range_ft":15,"requires_line_of_sight":true,"shape":"single"}}},{"id":"e47e71cb-f44e-402e-91af-e6fad63982dc","card_number":"prestidigitation","name":"Фокусы","before":{"description":"Вы создаёте один незначительный магический эффект в пределах дистанции (одновременно можно иметь до трёх немгновенных): безвредный ощутимый эффект — искры, ветерок, запах или мелодия; зажечь либо потушить маленький огонь; мгновенно очистить или испачкать предмет до 1 кубического фута; охладить.","detailed_description":"Вы создаёте магический эффект в пределах дистанции. Выберите один из нижеприведённых вариантов. Если вы сотворяете это заклинание несколько раз, вы можете иметь не более трёх немгновенных эффектов одновременно. Ощутимый эффект. Вы создаёте мгновенный безвредный ощутимый эффект, такой как сноп искр, порыв ветра, тихая мелодия или необычный запах.\n\nИгра с огнём. Вы мгновенно зажигаете или тушите свечу, факел или небольшой костёр. Очищение или загрязнение. Вы мгновенно чистите или мараете объект, размером не превышающий 1 кубического фута. Небольшое ощущение. Вы остужаете, нагреваете или придаёте запах не более, чем 1 кубическому футу неживой материи на 1 час. Волшебная метка.\n\nВы создаёте на поверхности или объекте маленькую цветную метку или символ, существующую 1 час. Небольшое сотворение. Вы создаёте немагическую безделушку или иллюзорный образ, помещающийся в вашу ладонь. Она существует до конца вашего следующего хода. Безделушка не наносит никакого урона и ничего не стоит.","upcast_description":null},"after":{"description":"Создайте безвредный сенсорный эффект; зажгите или потушите небольшой [fire]:fire:огонь[/fire]; очистите или испачкайте объект до 1 кубического фута; охладите, согрейте или придайте вкус неживой материи; оставьте цвет, метку или символ; создайте крошечную безделушку или иллюзорный образ. Одновременно можно поддерживать до трёх немгновенных эффектов.","detailed_description":"Вы создаёте один из следующих магических эффектов в пределах дистанции. При повторном сотворении одновременно могут действовать до трёх немгновенных эффектов этого заклинания.\n\n**Ощутимый эффект.** Мгновенный безвредный сенсорный эффект: сноп искр, порыв ветра, тихая мелодия или необычный запах.\n\n**Игра с огнём.** Вы мгновенно зажигаете или тушите свечу, факел или небольшой костёр.\n\n**Очищение или загрязнение.** Вы мгновенно очищаете или пачкаете объект объёмом не более 1 кубического фута.\n\n**Небольшое ощущение.** Вы охлаждаете, согреваете или придаёте вкус неживой материи объёмом до 1 кубического фута на 1 час.\n\n**Волшебная метка.** На объекте или поверхности на 1 час появляется выбранный цвет, небольшая метка или символ.\n\n**Небольшое сотворение.** Вы создаёте немагическую безделушку или иллюзорный образ, помещающийся в ладонь. Он существует до конца вашего следующего хода. Безделушка не наносит урона и не имеет денежной ценности.","upcast_description":null},"expected_mechanics":{"activation":{"cast_time":{"amount":1,"unit":"action"},"cost":[{"resource":"action"}],"mode":"active"},"effects":[{"resolution":"auto","result":[]}],"primitive":{"policy":{"attachment_duration_rounds":600,"creation_source_turn_endings":2,"max_active_effects":3,"max_volume_cubic_ft":1},"type":"prestidigitation_world"},"spell_class_list_ids":["CLASS-bard","CLASS-sorcerer","CLASS-warlock","CLASS-wizard"],"targeting":{"actor_targets":false,"allowed_relations":[],"domain":"world","filter":"any","max_targets":1,"min_targets":0,"range":"10 футов","range_ft":10,"requires_line_of_sight":false,"shape":"single"}}},{"id":"9c7cec56-53ed-43f1-8ba7-67d768cf28de","card_number":"SPELL-0315","name":"Чародейский выброс","before":{"description":"Вы направляете чародейскую энергию на одно существо или объект в пределах дистанции. Совершите бросок дальнобойной атаки по цели. При попадании цель получает 1к8 урона типа по вашему выбору: Звук, [acid]:acid:Кислота[/acid], Огонь, Психическая энергия, Холод, Электричество или Яд.","detailed_description":"Вы направляете чародейскую энергию на одно существо или объект в пределах дистанции. Совершите бросок дальнобойной атаки по цели. При попадании цель получает 1к8 урона типа по вашему выбору: Звук, [acid]:acid:Кислота[/acid], Огонь, Психическая энергия, Холод, Электричество или Яд.\n\nЕсли выпадет «8» на к8 для этого заклинания, дополнительно бросьте к8 и добавьте выпавшее значение к урону. При сотворении этого заклинания максимальное количество таких к8, которые вы можете добавить к урону заклинания, равно вашему модификатору заклинательной характеристики.","upcast_description":"Урон увеличивается на 1к8, когда вы достигаете 5‑го уровня (2к8), 11‑го уровня (3к8) и 17‑го уровня (4к8)."},"after":{"description":"Совершите дальнобойный [[бросок атаки|concept:attack_roll]] по одному существу или объекту в пределах дистанции. При попадании цель получает 1к8 урона выбранного типа: [thunder]:thunder:Звук[/thunder], [acid]:acid:Кислота[/acid], [fire]:fire:Огонь[/fire], [psychic]:psychic:Психическая энергия[/psychic], [cold]:cold:Холод[/cold], [lightning]:lightning:Электричество[/lightning] или [poison]:poison:Яд[/poison]. За каждую выпавшую 8 можно бросить дополнительную к8 и добавить её к урону; всего таких дополнительных костей за сотворение — не больше [[МЗ|concept:spellcasting_modifier]].","detailed_description":"Вы направляете чародейскую энергию на одно существо или объект в пределах дистанции. Совершите дальнобойный [[бросок атаки|concept:attack_roll]] по цели. При попадании она получает 1к8 урона выбранного типа: [thunder]:thunder:Звук[/thunder], [acid]:acid:Кислота[/acid], [fire]:fire:Огонь[/fire], [psychic]:psychic:Психическая энергия[/psychic], [cold]:cold:Холод[/cold], [lightning]:lightning:Электричество[/lightning] или [poison]:poison:Яд[/poison].\n\nЕсли на к8 этого заклинания выпадает 8, вы можете бросить ещё одну к8 и добавить результат к урону. Это относится и к дополнительным костям. За одно сотворение максимальное число дополнительных к8 равно [[МЗ|concept:spellcasting_modifier]].","upcast_description":"Урон увеличивается на 1к8, когда вы достигаете 5‑го уровня (2к8), 11‑го уровня (3к8) и 17‑го уровня (4к8)."},"expected_mechanics":{"activation":{"cost":[{"resource":"action"}],"mode":"active"},"effects":[{"ability":"spellcasting","attack_kind":"spell_ranged","on_hit":[{"context":"in_play","count":1,"id":"sorcerous_burst_damage_type","kind":"choice","options":{"items":[{"grants":[{"dice":"1d8","explode":{"limit":"spellcasting"},"kind":"damage","scaling":{"dice":"1d8","per":"character_level"},"type":"acid"}],"id":"acid","name":"Кислота"},{"grants":[{"dice":"1d8","explode":{"limit":"spellcasting"},"kind":"damage","scaling":{"dice":"1d8","per":"character_level"},"type":"cold"}],"id":"cold","name":"Холод"},{"grants":[{"dice":"1d8","explode":{"limit":"spellcasting"},"kind":"damage","scaling":{"dice":"1d8","per":"character_level"},"type":"fire"}],"id":"fire","name":"Огонь"},{"grants":[{"dice":"1d8","explode":{"limit":"spellcasting"},"kind":"damage","scaling":{"dice":"1d8","per":"character_level"},"type":"lightning"}],"id":"lightning","name":"Электричество"},{"grants":[{"dice":"1d8","explode":{"limit":"spellcasting"},"kind":"damage","scaling":{"dice":"1d8","per":"character_level"},"type":"poison"}],"id":"poison","name":"Яд"},{"grants":[{"dice":"1d8","explode":{"limit":"spellcasting"},"kind":"damage","scaling":{"dice":"1d8","per":"character_level"},"type":"psychic"}],"id":"psychic","name":"Психическая энергия"},{"grants":[{"dice":"1d8","explode":{"limit":"spellcasting"},"kind":"damage","scaling":{"dice":"1d8","per":"character_level"},"type":"thunder"}],"id":"thunder","name":"Звук"}],"source":"explicit"},"prompt":"Выберите тип урона"}],"resolution":"attack_roll","vs":"ac"}],"spell_class_list_ids":["CLASS-sorcerer"],"spell_variant_ids":["39c2b232-0719-565c-a403-cd8a96e974d2","e25e99b5-da59-5c37-a161-8e9f0e841b83","4b3dd04d-a5dd-5361-affc-adad6b910faa","e8999ba5-b479-51f2-aa66-6a9494d746f4","1ab7d99f-165c-537a-ae3a-b4f25992a97c","3c5011ec-6d21-56c2-a0be-579d075624e8","7f25634e-602d-5bfa-af57-acc04336b535"],"targeting":{"filter":"any","range":"120 футов","shape":"single"}}},{"id":"8b708d7b-097e-4624-8a41-c8c8e00f044c","card_number":"thaumaturgy","name":"Чудотворство","before":{"description":"Вы проявляете небольшое чудо в пределах дистанции. Вы создаёте один из приведённых ниже эффектов в пределах дистанции. При сотворении этого заклинания несколько раз вы можете иметь не более трёх активных эффектов с длительностью в 1 минуту одновременно.","detailed_description":"Вы проявляете небольшое чудо в пределах дистанции. Вы создаёте один из приведённых ниже эффектов в пределах дистанции. При сотворении этого заклинания несколько раз вы можете иметь не более трёх активных эффектов с длительностью в 1 минуту одновременно. Изменённые глаза. Вы изменяете внешний вид своих глаз на 1 минуту. Раскатистый голос.\n\nВаш голос звучит не более, чем в три раза громче обычного в течение 1 минуты. Пока заклинание активно, вы совершаете с [[Преимуществом|concept:advantage]] проверки Харизмы (Запугивание). Игра с огнём. Вы заставляете пламя мерцать, светить ярче, тусклее или изменять цвет в течение 1 минуты. Невидимая рука.\n\nВы мгновенно заставляете незапертое окно или дверь распахнуться или захлопнуться. Фантомный звук. Вы создаёте мгновенный звук, исходящий из выбранной вами точки в пределах дистанции, такой как раскат грома, крик ворона или зловещий шёпот. Дрожь. Вы вызываете безвредную дрожь в земле в течение 1 минуты.","upcast_description":null},"after":{"description":"Проявите одно небольшое чудо: измените глаза; усильте голос и получите [[Преимущество|concept:advantage]] на Запугивание; измените пламя; откройте или закройте незапертую дверь либо окно; создайте [thunder]:thunder:звук[/thunder] или дрожь земли. Одновременно можно иметь до трёх эффектов с длительностью 1 минута.","detailed_description":"Вы создаёте одно из следующих небольших чудес в пределах дистанции. При повторном сотворении одновременно могут действовать до трёх эффектов этого заклинания с длительностью 1 минута.\n\n**Изменённые глаза.** Вы меняете внешний вид своих глаз на 1 минуту.\n\n**Раскатистый голос.** Ваш голос до 1 минуты звучит до трёх раз громче обычного. Пока действует эффект, вы совершаете с [[Преимуществом|concept:advantage]] проверки Харизмы (Запугивание).\n\n**Игра с огнём.** Вы заставляете пламя мерцать, становиться ярче или тусклее либо менять цвет на 1 минуту.\n\n**Невидимая рука.** Вы мгновенно распахиваете или захлопываете незапертую дверь или окно.\n\n**Фантомный [thunder]:thunder:звук[/thunder].** Вы создаёте мгновенный [thunder]:thunder:звук[/thunder] из выбранной точки в пределах дистанции, например раскат грома, крик ворона или зловещий шёпот.\n\n**Дрожь.** Вы вызываете безвредную дрожь земли на 1 минуту.","upcast_description":null},"expected_mechanics":{"activation":{"cost":[{"resource":"action"}],"mode":"active"},"effects":[{"context":"in_play","count":1,"id":"thaumaturgy_effect","kind":"choice","options":{"items":[{"grants":[{"applies_to":{"filter":{"skill":"intimidation"},"roll":"ability_check"},"duration":{"amount":10,"type":"rounds"},"kind":"modifier","op":"advantage","source":"Чудотворство: раскатистый голос"}],"id":"booming_voice","name":"Раскатистый голос"},{"grants":[{"description":"Изменяет внешний вид глаз на 1 минуту.","kind":"narrative"}],"id":"eyes","name":"Изменённые глаза"},{"grants":[{"description":"Меняет вид пламени на 1 минуту.","kind":"narrative"}],"id":"flame","name":"Игра с огнём"},{"grants":[{"description":"Открывает или закрывает незапертую дверь либо окно.","kind":"narrative"}],"id":"door","name":"Невидимая рука"},{"grants":[{"description":"Создаёт мгновенный звук в выбранной точке.","kind":"narrative"}],"id":"sound","name":"Фантомный звук"},{"grants":[{"description":"Создаёт безвредную дрожь земли на 1 минуту.","kind":"narrative"}],"id":"tremor","name":"Дрожь"}],"source":"explicit"},"prompt":"Выберите чудо"}],"spell_class_list_ids":["CLASS-cleric"],"spell_variant_ids":["0809ec29-873b-56c3-afdf-645a949daccd","55f6d406-658f-58b2-a85d-96c34c4d377a","d485e17e-1dc5-5827-aed6-5240193aec9e","7e5a24b6-bc9f-519c-aa71-9dfb366933f4","0f854698-9ece-5dc5-a8fd-00dd1b38bdd1","7fc187b2-1653-591b-a718-629cef79848b"],"targeting":{"filter":"any","range":"30 футов","shape":"single"}}},{"id":"30530b80-5db9-4fd9-bae8-1cb092c05730","card_number":"SPELL-0319","name":"Электрошок","before":{"description":"Молния прыгает от вас к существу, которого вы пытаетесь коснуться. Совершите по цели рукопашную [[атаку заклинанием|concept:spell_attack]]. При попадании цель получает [lightning]1к8:lightning:электричеством[/lightning] и не может совершать Провоцированные атаки до начала своего следующего хода.","detailed_description":null,"upcast_description":"Урон увеличивается на 1к8, когда вы достигаете 5‑го уровня (2к8), 11‑го уровня (3к8) и 17‑го уровня (4к8)."},"after":{"description":"Молния прыгает от вас к существу, которого вы пытаетесь коснуться. Совершите по цели рукопашную [[атаку заклинанием|concept:spell_attack]]. При попадании цель получает [lightning]1к8:lightning:электричеством[/lightning] и не может совершать [[Провоцированные атаки|concept:opportunity_attacks]] до начала своего следующего хода.","detailed_description":"Молния прыгает от вас к существу, которого вы пытаетесь коснуться. Совершите по цели рукопашную [[атаку заклинанием|concept:spell_attack]]. При попадании цель получает [lightning]1к8:lightning:электричеством[/lightning] и не может совершать [[Провоцированные атаки|concept:opportunity_attacks]] до начала своего следующего хода.","upcast_description":"Урон увеличивается на 1к8, когда вы достигаете 5‑го уровня (2к8), 11‑го уровня (3к8) и 17‑го уровня (4к8)."},"expected_mechanics":{"activation":{"cost":[{"resource":"action"}],"mode":"active"},"effects":[{"ability":"spellcasting","attack_kind":"spell_melee","on_hit":[{"dice":"1d8","kind":"damage","scaling":{"dice":"1d8","per":"character_level"},"type":"lightning"},{"description":"До начала следующего хода цель не может совершать Провоцированные атаки.","kind":"narrative"}],"resolution":"attack_roll","vs":"ac"}],"spell_class_list_ids":["CLASS-sorcerer","CLASS-wizard"],"targeting":{"filter":"enemy","range":"Касание","shape":"single"}}},{"id":"7d0c00e7-0cfa-4f3f-8650-aac70150538c","card_number":"poison_spray","name":"Ядовитые брызги","before":{"description":"Вы распыляете токсичный туман на существо в пределах дистанции. Совершите Дальнобойную [[атаку заклинанием|concept:spell_attack]] по цели. При попадании цель получает [poison]1к12:poison:ядом[/poison].","detailed_description":null,"upcast_description":"Урон увеличивается на 1к12, когда вы достигаете 5‑го уровня (2к12), 11‑го уровня (3к12) и 17‑го уровня (4к12)."},"after":{"description":"Вы распыляете токсичный туман на существо в пределах дистанции. Совершите Дальнобойную [[атаку заклинанием|concept:spell_attack]] по цели. При попадании цель получает [poison]1к12:poison:ядом[/poison].","detailed_description":"Вы распыляете токсичный туман на существо в пределах дистанции. Совершите Дальнобойную [[атаку заклинанием|concept:spell_attack]] по цели. При попадании цель получает [poison]1к12:poison:ядом[/poison].","upcast_description":"Урон увеличивается на 1к12, когда вы достигаете 5‑го уровня (2к12), 11‑го уровня (3к12) и 17‑го уровня (4к12)."},"expected_mechanics":{"activation":{"cast_time":{"amount":1,"unit":"action"},"cost":[{"resource":"action"}],"mode":"active"},"effects":[{"ability":"spellcasting","attack_kind":"spell_ranged","on_hit":[{"dice":"1d12","kind":"damage","scaling":{"dice":"1d12","per":"character_level"},"type":"poison"}],"resolution":"attack_roll","vs":"ac"}],"interaction":{"intent":"harmful"},"spell_class_list_ids":["CLASS-druid","CLASS-sorcerer","CLASS-warlock","CLASS-wizard"],"targeting":{"actor_targets":true,"allowed_relations":["self","ally","enemy","neutral"],"domain":"actor","filter":"creature","max_targets":1,"min_targets":1,"range":"30 футов","range_ft":30,"requires_line_of_sight":true,"shape":"single"}}},{"id":"48f07634-634c-562c-a9c6-7e2e73cbb9d3","card_number":"SPELL-VAR-SPELL-0224-radiant","name":"Меткий удар — Излучение","before":{"description":"Руководствуясь вспышкой магической проницательности, вы совершаете одну атаку оружием, использованным при сотворении заклинания. Атака использует вашу заклинательную характеристику вместо Силы или Ловкости для бросков атаки и урона.\n\nЕсли атака наносит урон, это может быть урон [radiant]:radiant:Излучением [/radiant]или обычный урон от атаки этим оружием (по вашему выбору).\n\nВариант: Излучение.","detailed_description":null,"upcast_description":"Независимо от того, наносите ли вы урон [radiant]:radiant:Излучением[/radiant] или обычным типом урона оружия, атака наносит дополнительный урон [radiant]Излучением[/radiant], когда вы достигаете 5‑го уровня (1к6), 11‑го уровня (2к6) и 17‑го уровня (3к6)."},"after":{"description":"Руководствуясь магической проницательностью, вы совершаете одну атаку оружием, использованным как материальный компонент заклинания. Для [[бросков атаки|concept:attack_roll]] и урона используется ваша заклинательная характеристика вместо Силы или Ловкости.\n\nПри попадании атака наносит урон типа «[radiant]:radiant:Излучение[/radiant]». Начиная с 5-го уровня к нему добавляется урон типа «[radiant]:radiant:Излучение[/radiant]», указанный в усилении заговора.","detailed_description":"Руководствуясь магической проницательностью, вы совершаете одну атаку оружием, использованным как материальный компонент заклинания. Для [[бросков атаки|concept:attack_roll]] и урона используется ваша заклинательная характеристика вместо Силы или Ловкости.\n\nПри попадании атака наносит урон типа «[radiant]:radiant:Излучение[/radiant]». Начиная с 5-го уровня к нему добавляется урон типа «[radiant]:radiant:Излучение[/radiant]», указанный в усилении заговора.","upcast_description":"Атака наносит дополнительный урон [radiant]:radiant:Излучением[/radiant], когда вы достигаете 5‑го уровня (1к6), 11‑го уровня (2к6) и 17‑го уровня (3к6)."},"expected_mechanics":{"activation":{"cost":[{"resource":"action"}],"mode":"active"},"effects":[{"ability":"spellcasting","on_hit":[{"ability":"spellcasting","dice":"weapon","kind":"damage","type":"radiant"},{"dice":"0","kind":"damage","omit_if_zero":true,"scaling":{"dice":"1d6","per":"character_level"},"suppress_damage_modifiers":true,"type":"radiant"}],"resolution":"attack_roll","vs":"ac"}],"spell_class_list_ids":["CLASS-bard","CLASS-sorcerer","CLASS-warlock","CLASS-wizard"],"targeting":{"actor_targets":true,"allowed_relations":["enemy"],"domain":"actor","max_targets":1,"min_targets":1,"range_ft":600,"requires_line_of_sight":true,"shape":"single"},"variant_of_spell_id":"f5d4b18f-6212-47e7-ae0b-8dda2f84d4c2"}},{"id":"39400cef-bf13-50b6-a3c9-cf470dda1219","card_number":"SPELL-VAR-SPELL-0224-weapon","name":"Меткий удар — Обычный тип оружия","before":{"description":"Руководствуясь вспышкой магической проницательности, вы совершаете одну атаку оружием, использованным при сотворении заклинания. Атака использует вашу заклинательную характеристику вместо Силы или Ловкости для бросков атаки и урона.\n\nЕсли атака наносит урон, это может быть урон [radiant]:radiant:Излучением [/radiant]или обычный урон от атаки этим оружием (по вашему выбору).\n\nВариант: Обычный тип оружия.","detailed_description":null,"upcast_description":"Независимо от того, наносите ли вы урон [radiant]:radiant:Излучением[/radiant] или обычным типом урона оружия, атака наносит дополнительный урон [radiant]Излучением[/radiant], когда вы достигаете 5‑го уровня (1к6), 11‑го уровня (2к6) и 17‑го уровня (3к6)."},"after":{"description":"Руководствуясь магической проницательностью, вы совершаете одну атаку оружием, использованным как материальный компонент заклинания. Для [[бросков атаки|concept:attack_roll]] и урона используется ваша заклинательная характеристика вместо Силы или Ловкости.\n\nПри попадании атака наносит урон обычного типа этого оружия. Начиная с 5-го уровня к нему добавляется урон типа «[radiant]:radiant:Излучение[/radiant]», указанный в усилении заговора.","detailed_description":"Руководствуясь магической проницательностью, вы совершаете одну атаку оружием, использованным как материальный компонент заклинания. Для [[бросков атаки|concept:attack_roll]] и урона используется ваша заклинательная характеристика вместо Силы или Ловкости.\n\nПри попадании атака наносит урон обычного типа этого оружия. Начиная с 5-го уровня к нему добавляется урон типа «[radiant]:radiant:Излучение[/radiant]», указанный в усилении заговора.","upcast_description":"Атака наносит дополнительный урон [radiant]:radiant:Излучением[/radiant], когда вы достигаете 5‑го уровня (1к6), 11‑го уровня (2к6) и 17‑го уровня (3к6)."},"expected_mechanics":{"activation":{"cost":[{"resource":"action"}],"mode":"active"},"effects":[{"ability":"spellcasting","on_hit":[{"ability":"spellcasting","dice":"weapon","kind":"damage","type":"weapon"},{"dice":"0","kind":"damage","omit_if_zero":true,"scaling":{"dice":"1d6","per":"character_level"},"suppress_damage_modifiers":true,"type":"radiant"}],"resolution":"attack_roll","vs":"ac"}],"spell_class_list_ids":["CLASS-bard","CLASS-sorcerer","CLASS-warlock","CLASS-wizard"],"target