ription":"Вы мгновенно распахиваете или захлопываете одну незапертую дверь или окно в пределах дистанции.\n\nПри повторном сотворении Чудотворства одновременно могут действовать до трёх его эффектов с длительностью 1 минута.","upcast_description":null},"expected_mechanics":{"activation":{"cost":[{"resource":"action"}],"mode":"active"},"effects":[{"resolution":"auto","result":[{"description":"Открывает или закрывает незапертую дверь либо окно.","kind":"narrative"}]}],"spell_class_list_ids":["CLASS-cleric"],"targeting":{"filter":"any","range":"30 футов","shape":"single"},"variant_of_spell_id":"8b708d7b-097e-4624-8a41-c8c8e00f044c"}},{"id":"0809ec29-873b-56c3-afdf-645a949daccd","card_number":"SPELL-VAR-thaumaturgy-booming-voice","name":"Чудотворство — Раскатистый голос","before":{"description":"Вы проявляете небольшое чудо в пределах дистанции. Вы создаёте один из приведённых ниже эффектов в пределах дистанции. При сотворении этого заклинания несколько раз вы можете иметь не более трёх активных эффектов с длительностью в 1 минуту одновременно.\n\nВариант: Раскатистый голос.","detailed_description":"Вы проявляете небольшое чудо в пределах дистанции. Вы создаёте один из приведённых ниже эффектов в пределах дистанции. При сотворении этого заклинания несколько раз вы можете иметь не более трёх активных эффектов с длительностью в 1 минуту одновременно. Изменённые глаза. Вы изменяете внешний вид своих глаз на 1 минуту. Раскатистый голос.\n\nВаш голос звучит не более, чем в три раза громче обычного в течение 1 минуты. Пока заклинание активно, вы совершаете с [[Преимуществом|concept:advantage]] проверки Харизмы (Запугивание). Игра с огнём. Вы заставляете пламя мерцать, светить ярче, тусклее или изменять цвет в течение 1 минуты. Невидимая рука.\n\nВы мгновенно заставляете незапертое окно или дверь распахнуться или захлопнуться. Фантомный звук. Вы создаёте мгновенный звук, исходящий из выбранной вами точки в пределах дистанции, такой как раскат грома, крик ворона или зловещий шёпот. Дрожь. Вы вызываете безвредную дрожь в земле в течение 1 минуты.","upcast_description":null},"after":{"description":"Ваш голос на 1 минуту звучит до трёх раз громче обычного. Пока эффект активен, вы совершаете с [[Преимуществом|concept:advantage]] проверки Харизмы (Запугивание).\n\nПри повторном сотворении Чудотворства одновременно могут действовать до трёх его эффектов с длительностью 1 минута.","detailed_description":"Ваш голос на 1 минуту звучит до трёх раз громче обычного. Пока эффект активен, вы совершаете с [[Преимуществом|concept:advantage]] проверки Харизмы (Запугивание).\n\nПри повторном сотворении Чудотворства одновременно могут действовать до трёх его эффектов с длительностью 1 минута.","upcast_description":null},"expected_mechanics":{"activation":{"cost":[{"resource":"action"}],"mode":"active"},"effects":[{"resolution":"auto","result":[{"applies_to":{"filter":{"skill":"intimidation"},"roll":"ability_check"},"duration":{"amount":10,"type":"rounds"},"kind":"modifier","op":"advantage","source":"Чудотворство: раскатистый голос"}]}],"spell_class_list_ids":["CLASS-cleric"],"targeting":{"filter":"any","range":"30 футов","shape":"single"},"variant_of_spell_id":"8b708d7b-097e-4624-8a41-c8c8e00f044c"}},{"id":"0f854698-9ece-5dc5-a8fd-00dd1b38bdd1","card_number":"SPELL-VAR-thaumaturgy-sound","name":"Чудотворство — Фантомный звук","before":{"description":"Вы проявляете небольшое чудо в пределах дистанции. Вы создаёте один из приведённых ниже эффектов в пределах дистанции. При сотворении этого заклинания несколько раз вы можете иметь не более трёх активных эффектов с длительностью в 1 минуту одновременно.\n\nВариант: Фантомный звук.","detailed_description":"Вы проявляете небольшое чудо в пределах дистанции. Вы создаёте один из приведённых ниже эффектов в пределах дистанции. При сотворении этого заклинания несколько раз вы можете иметь не более трёх активных эффектов с длительностью в 1 минуту одновременно. Изменённые глаза. Вы изменяете внешний вид своих глаз на 1 минуту. Раскатистый голос.\n\nВаш голос звучит не более, чем в три раза громче обычного в течение 1 минуты. Пока заклинание активно, вы совершаете с [[Преимуществом|concept:advantage]] проверки Харизмы (Запугивание). Игра с огнём. Вы заставляете пламя мерцать, светить ярче, тусклее или изменять цвет в течение 1 минуты. Невидимая рука.\n\nВы мгновенно заставляете незапертое окно или дверь распахнуться или захлопнуться. Фантомный звук. Вы создаёте мгновенный звук, исходящий из выбранной вами точки в пределах дистанции, такой как раскат грома, крик ворона или зловещий шёпот. Дрожь. Вы вызываете безвредную дрожь в земле в течение 1 минуты.","upcast_description":null},"after":{"description":"Вы создаёте мгновенный [thunder]:thunder:звук[/thunder] из выбранной точки в пределах дистанции: например, раскат грома, крик ворона или зловещий шёпот.\n\nПри повторном сотворении Чудотворства одновременно могут действовать до трёх его эффектов с длительностью 1 минута.","detailed_description":"Вы создаёте мгновенный [thunder]:thunder:звук[/thunder] из выбранной точки в пределах дистанции: например, раскат грома, крик ворона или зловещий шёпот.\n\nПри повторном сотворении Чудотворства одновременно могут действовать до трёх его эффектов с длительностью 1 минута.","upcast_description":null},"expected_mechanics":{"activation":{"cost":[{"resource":"action"}],"mode":"active"},"effects":[{"resolution":"auto","result":[{"description":"Создаёт мгновенный звук в выбранной точке.","kind":"narrative"}]}],"spell_class_list_ids":["CLASS-cleric"],"targeting":{"filter":"any","range":"30 футов","shape":"single"},"variant_of_spell_id":"8b708d7b-097e-4624-8a41-c8c8e00f044c"}}]}$cantrip_plan$::jsonb);
DO $cantrip_apply$
DECLARE
  plan jsonb;
  current_row spells%ROWTYPE;
  current_text jsonb;
  updated_row jsonb;
  definition jsonb;
  concept_uuid uuid;
  operation_hash text := 'ae395fe95d64803c8f1b20e23aa2c403aeb41240c4a65272c060c3e43ff6b835';
  audit_kind text := 'cantrip-editorial-20261014:ae395fe95d64803c8f1b20e23aa2c403aeb41240c4a65272c060c3e43ff6b835';
  previously_applied boolean;
  changed integer := 0;
BEGIN
  IF NOT EXISTS(SELECT 1 FROM schema_migrations WHERE version='307_catalog_presentation')
    OR to_regclass('entity_presentation_307_audit') IS NULL
    OR to_regclass('entity_presentation_307_receipt') IS NULL THEN
    RAISE EXCEPTION 'Verified presentation schema must already exist';
  END IF;
  SELECT EXISTS(SELECT 1 FROM entity_presentation_307_receipt WHERE manifest_hash=operation_hash) INTO previously_applied;
  SELECT payload->'concept' INTO definition FROM cantrip_editorial_plan;
  SELECT id INTO concept_uuid FROM concepts WHERE concept_id=definition->>'concept_id' AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN
    IF previously_applied THEN RAISE EXCEPTION 'Previously created glossary concept is missing'; END IF;
    INSERT INTO concepts(concept_id,name,name_en,description,sort_order)
      VALUES(definition->>'concept_id',definition->>'name',definition->>'name_en',definition->>'description',(definition->>'sort_order')::integer)
      RETURNING id INTO concept_uuid;
    INSERT INTO entity_presentation_307_audit(entity_type,entity_id,row_before)
      VALUES(audit_kind||':concept',concept_uuid,'{"absent":true}'::jsonb);
  END IF;
  IF NOT EXISTS(SELECT 1 FROM concepts WHERE id=concept_uuid AND name=definition->>'name' AND deleted_at IS NULL) THEN
    RAISE EXCEPTION 'Glossary identity differs';
  END IF;
  FOR plan IN SELECT value FROM cantrip_editorial_plan,jsonb_array_elements(payload->'entries') ORDER BY value->>'id' LOOP
    SELECT * INTO current_row FROM spells WHERE id=(plan->>'id')::uuid AND deleted_at IS NULL FOR UPDATE;
    IF NOT FOUND OR current_row.card_number IS DISTINCT FROM plan->>'card_number'
      OR current_row.name IS DISTINCT FROM plan->>'name' OR current_row.level IS DISTINCT FROM 0 THEN
      RAISE EXCEPTION 'Cantrip identity drift: %',plan->>'card_number';
    END IF;
    IF current_row.mechanics IS DISTINCT FROM plan->'expected_mechanics' THEN
      RAISE EXCEPTION 'Cantrip mechanics drift: %',plan->>'card_number';
    END IF;
    current_text:=jsonb_build_object('description',current_row.description,'detailed_description',current_row.detailed_description,'upcast_description',current_row.upcast_description);
    IF current_text=plan->'after' THEN CONTINUE; END IF;
    IF previously_applied OR current_text IS DISTINCT FROM plan->'before' THEN
      RAISE EXCEPTION 'Cantrip prose drift: %',plan->>'card_number';
    END IF;
    INSERT INTO entity_presentation_307_audit(entity_type,entity_id,row_before)
      VALUES(audit_kind||':spell',current_row.id,to_jsonb(current_row));
    UPDATE spells SET description=plan->'after'->>'description',
      detailed_description=plan->'after'->>'detailed_description',
      upcast_description=plan->'after'->>'upcast_description',updated_at=NOW()
      WHERE id=current_row.id RETURNING to_jsonb(spells) INTO updated_row;
    IF (updated_row-ARRAY['description','detailed_description','upcast_description','updated_at'])
      IS DISTINCT FROM (to_jsonb(current_row)-ARRAY['description','detailed_description','upcast_description','updated_at']) THEN
      RAISE EXCEPTION 'Non-editorial field changed: %',plan->>'card_number';
    END IF;
    changed:=changed+1;
  END LOOP;
  IF NOT previously_applied THEN
    INSERT INTO entity_presentation_307_receipt(manifest_hash) VALUES(operation_hash);
  END IF;
  RAISE NOTICE 'Cantrip editorial: % rows updated; receipt %',changed,operation_hash;
END;
$cantrip_apply$;
COMMIT;
